       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"6d0fe669-b29b-5635-b852-d0b2b153bd34","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتسبب يف إصابة- مطالبة املدعي باملجازاة -إيجابية التقريرين الطبين للمدعى - إقرار املدعى عليه بالدعوى -إدانة املدعى عليه.","document_number":"34348135","case_number":"34325504","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/3","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتسبب يف إصابة- مطالبة املدعي باملجازاة -إيجابية التقريرين الطبين للمدعى - إقرار املدعى عليه بالدعوى -إدانة املدعى عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/11/3 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34348135 :‬‬\n                   ‫َر ْق ُم الدعوى‪34325504 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34390495‬تاريخه‪1434/12/29:‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالضــرب وتســبب يف إصابــة‪-‬‬\n‫مطالبــة املدعــي باملجــازاة ‪ -‬إيجابيــة التقريريــن الطبيــن للمدعــى ‪-‬‬\n                ‫إقــرار املدعــى عليــه بالدعــوى ‪ -‬إدانــة املدعــى عليــه‪.‬‬\n\n\n\n\n                                                          ‫املرء مؤاخذ بإقراره‪.‬‬\n\n\n\n\n‫ادعــى وكيــل املدعــي بــأن املدعــى عليــه احلاضــر معــه قــام باالعتــداء‬\n‫علــى موكلــه بالضــرب ممــا تســبب يف إصابتــه بكدمــات يف الوجــه‬\n‫وكســر لبعــض األســنان‪ ،‬ولــذا فقــد طلــب احلكــم عليه بعقوبــة تعزيرية‬\n‫لقــاء ذلــك ‪ -‬أقــر املدعــى عليــه مبــا جــاء يف الدعــوى جملــة وتفصيــا‪-‬‬\n‫املدعــى عليــه تســبب يف إصابــة املدعــي بكدمــات مــع تــورم علــى العــن‬\n‫اليســرى وكدمــات يف الوجــه وكســر ثالثــة أســنان أماميــة فوقيــة‬\n‫ومــدة الشــفاء املتوقعــة تصــل إلــى أســبوعني حســب التقريريــن الطبيــن‬\n‫‪ -‬قضــت احملكمــة بإدانــة املدعــى عليــه مبــا نســب إليــه وقــررت ســجنه‬\n‫ملــدة عشــرين يومـ ًا وجلــده أربعــن جلــدة دفعــة واحــدة‪ -‬قنــع املدعــى عليــه‬\n\n\n                                                                                      ‫‪368‬‬\n\f      ‫باحلكــم وعــارض عليــه وكيــل املدعــي‪ -‬قــررت محكمــة االســتئناف‬\n                                                  ‫املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪1434/11/3‬ه ـ لدي أنا‬\n      ‫ـاء علــى املعاملــة احملالــة‬\n                                 ‫‪ ......‬القاضــي باحملكمــة اجلزائيــة بالدمــام وبنـ ً‬\n      ‫إلينــا مــن رئيــس احملكمــة برقــم (‪ )34325504‬وتاريــخ ‪1434/4/3‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر ‪ ....‬ســعودي مبوجــب الهويــة الوطنيــة رقــم‬\n      ‫(‪ )...‬الوكيــل الشــرعي عــن مبوجــب الوكالــة الصــادرة من كتابة عدل‬\n      ‫الباحــة برقــم (‪ )33426118‬و تاريــخ ‪1433/10/15‬ه ـ والتــي تخولــه‬\n      ‫املرافعــة واملدافعــة و الصلــح والتنــازل و قبــول احلكــم واالعتــراض عليــه‬\n      ‫و ادعــى علــى احلاضــر معــه ‪ ....‬ســعودي مبوجــب بطاقــة الهويــة الوطنيــة‬\n      ‫ا يف دعــواه لقــد تعــرض موكلــي لالعتــداء بالضــرب‬          ‫رقــم (‪ ).....‬قائ ـ ً‬\n      ‫مــن قبــل املدعــى عليــه و قــد نتــج عــن ذلــك إصابــات يف موكلــي عبــارة‬\n      ‫عــن كدمــات مــع تــورم علــى العــن اليســرى و كدمــات علــى الوجــه و‬\n      ‫كســر ثالثــة أســنان أماميــة فوقيــة أطلــب احلكــم بتعزيــره لقــاء ذلــك‬\n      ‫هــذه دعــواي وأحصرهــا يف ذلــك و أســأله اإلجابــة و بســؤال املدعــى‬\n      ‫عليــه أجــاب بقولــه مــا ذكــره املدعــي وكالــة يف دعــواه صحيــح فقــد‬\n      ‫قمــت باالعتــداء بضــرب موكلــه و أنــا نــادم علــى مــا بــدر منــي هــذه‬\n      ‫إجابتــي و بعــد تدويــن مــا ســبق جــرى االطــاع علــى التقريــر الطبــي‬\n      ‫الصــادر مــن مجمــع الدمــام الطبــي برقــم (‪16/18096‬ت‪ )41/‬و تاريــخ‬\n      ‫‪1432/10/22‬ه ـ و التقريــر الطبــي اإلحلاقــي لــه و املــدون علــى اللفــة‬\n      ‫السادســة عشــرة فوجــدت اإلصابــات التــي حلقــت مــوكل املدعــي‬\n\n‫‪369‬‬\n\f‫مطابقــة ملــا ورد يف الدعــوى و مــدة الشــفاء يف الكدمــات التــي علــى‬\n‫العــن و الوجــه وكســر األســنان خمســة أيــام و مــدة شــفاء الســن القاطــع‬\n‫األمامــي العلــوي والســن القاطــع األمامــي اجلانبــي األميــن و الســن القاطــع‬\n‫الســفلي اجلانبــي األميــن مــن يــوم إلــى أســبوعني فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة املتضمنــة املصادقــة و حيــث إن املــرء مؤاخــذ بإقــراره‬\n‫وبنــاء علــى التقريريــن الطبيــن املشــار لهمــا أعــاه و حيــث إن مــا قــام‬\n‫بــه املدعــى عليــه فعــل محــرم وفيــه اعتــداء علــى اآلخريــن وســامتهم‬\n‫وموجــب ذلــك التعزيــر و حيــث حصــر املدعــي وكالــة دعــواه يف ذلــك‬\n‫لــذا فقــد حكمــت بســجن املدعــى عليــه عشــرين يوم ـ ًا وجلــده أربعــن‬\n‫جلــدة دفعــة واحــدة و بعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n‫قناعتــه بــه وقــرر املدعــي وكالــة عــدم القناعــة وطلــب رفــع احلكــم‬\n‫إلــى محكمــة االســتئناف بالئحــة فأجيــب لطلبــه ومت تســليمه نســخة‬\n‫مــن احلكــم وأفهــم بتقــدمي اعتراضــه خــال مهلــة ثالثــن يوم ـ ًا وأنــه إذا‬\n‫انتهــت هــذه املهلــة ولــم يتقــدم باعتراضــه ســقط حقــه يف ذلــك وســوف‬\n‫يتــم رفــع احلكــم إلــى محكمــة االســتئناف بــدون الئحــة وبــاهلل التوفيــق‬\n           ‫وصلــى اهلل علــى نبينــا محمــد و بــه حــرر يف ‪1434/11/3‬ه ـ ‪.‬‬\n‫ويف يــوم االثنــن املوافــق ‪1435/1/29‬ه ـ افتتحــت اجللســة الســاعة‬\n‫الثانيــة عشــرة وقــد عــادت املعاملــة مــن محكمــة االســتئناف برقــم‬\n‫(‪ )34/2730007‬وتاريــخ ‪1435/1/23‬ه ـ املتعلقــة بدعــوى ‪ ...‬ضــد ‪...‬‬\n‫وبرفقهــا القــرار الصــادر مــن الدائرة اجلزائية الثانية برقم (‪)34390495‬‬\n‫وتاريــخ ‪1434/12/29‬ه ـ املتضمــن املصادقــة علــى احلكــم لــذا جــرى‬\n‫إحلــاق ذلــك حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                  ‫وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n\n\n                                                                                        ‫‪370‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":368,"source_page_end":370,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d0cb43de98d15a21dedd6927a8b5d6a42e794fb7d44c2b4e2be590fdf57ad52f","normalized_text_hash":"9e2adfe58af42b722a5a6617728cf410065d436c0e74f0bfb05685c2affc923f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p368-34348135"},{"id":"181937f4-0708-5733-9647-e71cf074bf15","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالسب والشتم والتعيير -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعي غير موصلة -مين املدعى عليه على نفي الدعوى -إقرار املدعى عليه بالتعيير -إدانة املدعى عليه بالتعيير.","document_number":"34290521","case_number":"34357162","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/7","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالسب والشتم والتعيير -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعي غير موصلة -مين املدعى عليه على نفي الدعوى -إقرار املدعى عليه بالتعيير -إدانة املدعى عليه بالتعيير.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/8/7 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34290521 :‬‬\n                         ‫َر ْق ُم الدعوى‪34357162 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34311739‬تاريخه‪1434/9/3:‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالســب والشــتم والتعيير ‪ -‬مطالبة‬\n      ‫املدعــي باملجــازاة ‪ -‬إنــكار املدعــى عليــه الدعــوى ‪ -‬بينــة املدعــي غيــر‬\n      ‫موصلــة ‪ -‬ميــن املدعــى عليــه علــى نفــي الدعــوى ‪ -‬إقــرار املدعــى عليــه‬\n                                       ‫بالتعييــر ‪ -‬إدانــة املدعــى عليــه بالتعييــر‪.‬‬\n\n\n\n\n                                      ‫‪ -1‬قوله تعالى‪ (( :‬وال تنابزوا باأللقاب))‪.‬‬\n      ‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬كل املســلم علــى املســلم حــرام‬\n                                               ‫دمــه ومالــه وعرضــه) رواه مســلم‪.‬‬\n                                                                ‫‪ -3‬العادة محكمة‪.‬‬\n\n\n\n      ‫ادعــت املدعيــة بــأن املدعــى عليــه قــام بســبها وشــتمها وتعييرهــا بــأن‬\n      ‫زواجهــا غيــر شــرعي‪ ،‬وطلبــت احلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلك‪-‬‬\n      ‫أنكــر املدعــى عليــه مــا جــاء يف دعــوى املدعيــة ســوى أنــه وصــف زواجها‬\n      ‫بأنــه زواج مســيار‪ -‬طلبــت احملكمــة مــن املدعيــة أن تقــدم بينتهــا علــى‬\n      ‫دعواهــا فأحضــرت شــاهدين إال أن شــهادتهما غيــر موصلــة إلثبــات‬\n      ‫دعواهــا‪ -‬طلبــت املدعيــة ميــن املدعــى عليــه علــى نفــي دعواهــا فأداهــا‬\n      ‫طبــق مــا طلــب منــه‪ -‬املدعــى عليــه أقــر بأنــه وصــف زواج املدعيــة بأنــه‬\n\n‫‪371‬‬\n\f‫مســيار علــى ملــئ مــن النــاس وهــذا يعــد عرفـ ًا مــن قبيــل التعييــر كمــا‬\n‫أن شــهادة الشــهود قرينــة قويــة علــى كثــرة تعرضــه للمدعيــة باإلســاءة‬\n‫واإليــذاء اللفظــي‪ -‬قضــت احملكمــة بعــدم ثبــوت دعــوى املدعيــة بتلفــظ‬\n‫املدعــى عليــه مبــا جــاء يف دعواهــا كمــا قضــت بإدانــة املدعــى عليــه‬\n‫بتعييــر املدعيــة وإيذائهــا وقــررت ســجنه ملــدة خمســة عشــر يوم ـاً‪-‬‬\n‫قنعــت املدعيــة باحلكــم وعــارض عليــه املدعــى عليــه‪ -‬قــررت محكمــة‬\n                                           ‫االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن ‪1434/8/1‬ه ـ ويف متــام الســاعة‬\n‫التاســعة والنصــف افتتحــت اجللســة لــدي أنــا ‪ .....‬املــازم القضائــي‬\n‫باحملكمــة اجلزائيــة بابهــا واملكلــف بنظــر هــذه القضيــة مــن قبــل‬\n‫ـاء علــى املعاملــة‬\n                  ‫فضيلــة رئيــس احملكمــة اجلزائيــة بابهــا املســاعد وبنـ ً‬\n‫احملالــة لنــا مــن فضيلــة برقــم ‪ 34357162‬بتاريــخ ‪1434/8/1‬هـ واملقيدة‬\n‫باحملكمــة برقــم ‪ 341855532‬بتاريــخ ‪1434/8/1‬ه ـ وفيهــا حضــرت‬\n‫‪ ........‬ســعودية اجلنســية بالســجل املدنــي رقــم ‪ ......‬ويرافقهــا والدهــا‬\n‫واملعــرف بهــا ‪ ....‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪ ......‬وحضــر‬\n‫حلضورهــا ‪ ....‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪ .....‬وادعــت األولــى‬\n‫قائلــة ان هــذا احلاضــر معــي قــام بشــتمي وســبي وتعييــري أمــام النــاس‬\n‫واألقــارب يف املناســبات واالجتماعــات وقــال ان زواجــي مــن زوجــي‬\n‫غيــر شــرعي اطلــب إثبــات ذلــك ومعاقبتــه عليــه شــرعا هــذه دعــواي‬\n‫وبعرضــه علــى املدعــى عليــه أجــاب بــان مــا ذكرتــه املدعيــة يف دعواهــا‬\n‫غيــر صحيــح وكل مــا ذكرتــه ان زواجهــا دخلــي وهــو أشــبه باملســيار‬\n\n                                                                                    ‫‪372‬‬\n\f      ‫وبســؤاله هــل كان ذلــك يف مجمــع مــن النــاس فأجــاب بأنــه اســتفزه‬\n      ‫احــد اقاربهــا فذكــر مــا ذكــر امــام النــاس وبعرضــه علــى املدعيــة‬\n      ‫اجابــت بــان الصحيــح مــا ذكرتــه يف دعــواي وبســؤال املدعيــة هــل لديهــا‬\n      ‫بينــه علــى مــا ذكــرت اجابــت بــان لديهــا شــهود يشــهدون بأنــه قــال ان‬\n      ‫زواجــي مــن زوجــي غيــر شــرعي واطلــب امهالــي إلحضارهــم فأجبتهــا‬\n      ‫لطلبهــا ورفعــت اجللســة لذلــك حتــى يــوم األحــد ‪1434/8/7‬ه ـ الســاعة‬\n      ‫التاســعة وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬احلمــد اهلل وحــدة وبعــد‬\n      ‫ويف يــوم األحــد ‪1434/8/7‬ه ـ ويف متــام الســاعة احلاديــة عشــرة فتحــت‬\n      ‫اجللســة بحضــور الطرفــان واملعــرف باملدعــى عليهــا وبســؤال املدعيــة عــن‬\n      ‫بينتهــا التــي اســتمهلت مــن أجلهــا احضــرت للشــهادة وادائهــا ســعودي‬\n      ‫اجلنســية بالســجل املدنــي رقــم ســعودي اجلنســية بالســجل املدنــي رقــم‬\n      ‫وشــهد األول قائــا اننــا كنــا يف املستشــفى ودخــل علينــا املدعــى عليــه‬\n      ‫وقــال خلنــي اشــوف هــذا الــذي حذائــي اكــرم مــن وجهــة اللــي زوج بنتــه‬\n      ‫مســيار اشــهد بــاهلل العظيــم علــى ذلــك وشــهد الثانــي قائــا بأننــا كنــا‬\n      ‫يف جلســة عشــاء عنــد احــد اعمامــي وكان املدعــى عليــه موجــود يف‬\n      ‫اجللســة فقــال لــي ان عمــك حطهــا مجــراره ســكن زوجهــا عنــده حتــت‬\n      ‫فقلــت لــه ترضــاه ألختــك او بنــت اختــك فقــال ال أعمــل جــرار واشــهد اهلل‬\n      ‫العظيــم علــى ذلــك وبعــرض الشــهود وشــهادتهم علــى املدعــى عليــه اجاب‬\n      ‫قائــا بانــي اعــرف الشــهود عــم املدعيــة و ابــن عمهــا وال اقبــل شــهادتهم‬\n      ‫وأمــا الشــهادة فإننــي بالفعــل قلــت بــان الــزواج مســيار النهــم منعونــي‬\n      ‫مــن الدخــول علــى اختــي التــي هــي أمهــا وأنــا لــم اقــل إال انــه مســيار‬\n      ‫وبســؤال املدعــى عليهــا هــل لديهــا مزيــد بينــة علــى دعواهــا اجابــت بانــه‬\n      ‫ليــس عندهــا اال مــا ذكــر فأفهمــت املدعيــة بــان بينتهــا غيــر موصلــة‬\n\n\n‫‪373‬‬\n\f‫وانــه ليــس لهــا اال ميــن املدعــى عليــه علــى نفــي دعواهــا فقــررت رغبتهــا‬\n‫فيهــا لذلــك جــرى توجيــه اليمــن علــى املدعــى عليــه بعــد تخويفــه مــن‬\n‫خطرهــا فاســتعد لبذلهــا وحلــف قائــا واهلل العظيــم اننــي لــم اتلفــظ‬\n‫علــى املدعيــة بقولــي ان زواجهــا غيــر شــرعي وال أي لفــظ يســئ لشــرفها‬\n‫واهلل العظيــم هكــذا حلــف فبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــة‬\n‫وملــا قــرره الطرفــان ونظــرا إلنــكار املدعــى عليــه انــه قــال للمدعيــة بــان‬\n‫زواجهــا غيــر شــرعي ولقصــور بينتهــا وعــدم اتفــاق الشــهود علــى لفــظ‬\n‫الدعــوى ولبذلــه اليمــن علــى ذلــك بعــد ان طلبتهــا املدعيــة وإلقــراره‬\n‫بنبزهــا بــان زواجهــا مســيار امــام جمــع مــن النــاس وهــذا ممــا يعــاب عنــد‬\n‫اهــل املنطقــة والن العــادة محكمــة كمــا قــرر الفقهــاء وملــا شــهد بــه‬\n‫الشــهود مــن شــهادة تعــد قرينــه قويــة علــى إســاءته لهــا وكثــر وايذائهــا‬\n‫بلســانه ولقولــه صلــى اهلل عليــه وســلم (كل املســلم علــى املســلم حــرام‬\n‫دمــه ومالــه وعرضــه) رواه مســلم ولقولــه تعالــى ( وال تنابــزوا باأللقــاب)‬\n‫لذلــك كلــه فلــم يثبــت لــدي تلفــظ املدعــى عليــه علــى املدعيــة بقولــه‬\n‫بــان زواجهــا غيــر شــرعي وثبــت لــدي انــه أذاهــا وعيرهــا بــان زواجهــا‬\n‫مســيار وحكمــت بتعزيــر املدعــى عليــه بســجنه خمســة عشــر يومـ ًا لقــاء‬\n‫ذلــك وبهــذا حكمــت وبعــرض احلكــم علــى الطرفــن قــررت املدعيــة‬\n‫القناعــة بــه وقــرر املدعــى عليــه اعتراضــه عليــه مــن غيــر الئحــة وســوف‬\n‫يتــم رفــع كامــل املعاملــة إلــى محكمــة االســتئناف لتدقيــق احلكــم‬\n‫كاملتبــع‪ .‬جــرى النطــق باحلكــم بتاريــخ ‪1434/8/7‬ه ـ ورفعــت اجللســة‬\n‫بعــد ذلــك عنــد الســاعة احلاديــة عشــرة والنصــف وصلــى اهلل وســلم علــى‬\n                                                                   ‫نبينــا محمــد ‪.‬‬\n‫ويف يــوم األربعــاء ‪1434/10/ 7‬ه ـ افتتحــت اجللســة يف متــام الســاعة‬\n\n\n                                                                                       ‫‪374‬‬\n\f      ‫الواحدة ظهر ًا وفيها عادت املعاملة رفق خطاب فضيلة رئيس محكمة‬\n      ‫االســتئناف مبنطقــة عســير رقــم ‪ 342046767‬يف ‪1434/9/16‬ه ـ‬\n      ‫مرفقــا بهــا قــرار التصديــق الصــادر مــن الدائــرة اجلزائيــة الثانيــة رقــم‬\n      ‫‪ 34311739‬يف ‪1434/9/3‬ه ـ املتضمــن نــص احلاجــة منــه مــا يلــي‬\n      ‫(وبدراســة القــرار وصــورة ضبطــه وأراق املعاملــة تقــررت املوافقــة علــى‬\n      ‫احلكــم واهلل املوفــق ) انتهــى بتوقيــع وختــم قاضــي اســتئناف الشــيخ‪/‬‬\n      ‫(‪ ).....‬وبتوقيــع وختــم قاضــي اســتئناف الشــيخ‪ ).....(/‬وبتوقيــع وختــم‬\n      ‫رئيــس الدائــرة الشــيخ‪ ).....(/‬ولــذا جــرى مبوجبــه التهميــش ورفعــت‬\n      ‫اجللســة عنــد الســاعة الواحــدة والربــع وصلــى اهلل وســلم علــى نبينــا‬\n                                                                               ‫محمــد‪.‬‬\n\n\n\n\n‫‪375‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":371,"source_page_end":375,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d550c0fa6130456cce6b9eb58be40d46a3ce2e29e245fd912cecf4f4def6e112","normalized_text_hash":"a7c8258e583b7b2cb7c76ef361f518af02793e234547a72d431f39f949e612b9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p371-34290521"},{"id":"2264ceb8-5a79-5967-bdbf-a6fd923c506e","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتهديد بالقتل -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -عجز املدعي عن إقامة البينة -مين املدعى عليه على نفي الدعوى -رد الدعوى.","document_number":"34349902","case_number":"34429222","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/4","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتهديد بالقتل -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -عجز املدعي عن إقامة البينة -مين املدعى عليه على نفي الدعوى -رد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/11/4 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34349902 :‬‬\n                   ‫َر ْق ُم الدعوى‪34429222 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34363059‬تاريخه‪1434/11/19 :‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالضــرب وتهديــد بالقتل ‪ -‬مطالبة‬\n‫املدعــي باملجــازاة ‪ -‬إنــكار املدعــى عليــه الدعــوى ‪ -‬عجــز املدعــي عــن‬\n ‫إقامــة البينــة‪ -‬ميــن املدعــى عليــه علــى نفــي الدعــوى ‪ -‬رد الدعــوى‪.‬‬\n\n\n\n\n‫قــول النبــي صلــى اهلل عليــه وســلم ‪( :‬البينــة علــى املدعــي واليمــن علــى‬\n                                                                 ‫املدعــى عليه)‪.‬‬\n\n\n\n‫ادعــى املدعــي علــى املدعــى عليهمــا بــأن األول قــام بالتعــاون مــع الثانــي‬\n‫بضربــه علــى وجهــه وتهديــده بالقتــل‪ ،‬ولــذا فقــد طلــب احلكــم عليهمــا‬\n‫بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أنكــر املدعــى عليهمــا مــا جــاء يف الدعــوى‬\n‫جملــة وتفصيــا‪ -‬املدعــي ال بينــة لــه علــى إثبــات دعــواه وطلــب ميــن‬\n‫املدعــى عليهمــا علــى نفيهــا فأدياهــا طبــق مــا طلــب منهمــا‪ -‬قضــت‬\n‫احملكمــة بصــرف النظــر عــن دعــوى املدعــي وأخلــت ســبيل املدعــى‬\n‫عليهمــا منهــا ‪ -‬قنــع املدعــى عليهمــا باحلكــم وعــارض عليــه املدعــي ‪-‬‬\n                    ‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n                                                                                     ‫‪376‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بحائــل برقــم ‪ 34429222‬وتاريــخ ‪ 1434/09/17‬ه ـ املقيــدة‬                ‫ّ‬\n      ‫باحملكمــة برقــم ‪ 342205090‬وتاريــخ ‪ 1434/09/17‬ه ـ ففــي يــوم‬\n      ‫الثالثــاء املوافــق‪ 1434/11/04‬ه ـ افتتحــت اجللســة الســاعة احلاديــة‬\n      ‫عشــرة وفيهــا حضــر (‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم (‪ ).....‬وادعــى كل مــن (‪ ).....‬ســعودي مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪ ).....‬و(‪ ).....‬ســعودي مبوجــب الســجل املدنــي رقــم(‪ ).....‬قائــا يف حترير‬\n      ‫دعــواه إنــي كنــت يف مزرعــة والــدي أعمــل علــى احلراثــة فدخلــت علــي‬\n      ‫ســيارة يقودهــا املدعــى عليــه األول (‪ ).....‬وبصحبتــه ابنــه املدعــى عليــه‬\n      ‫الثانــي (‪ ).....‬فقــال لــي املدعــى عليــه األول وش عنــدك بهذا فقلت أحرث‬\n      ‫فقــال مــن أنــت ابــن لــه فقلــت ولــد فقــال تعــال انــزل ثــم نــزل ومــد يــده إلــي‬\n      ‫فأنزلنــي بالقــوة فحاولــت أدافــع عــن نفســي فقــام املدعــى عليــه الثانــي‬\n      ‫(‪ ).....‬مبســكي مــع رقبتــي وضربنــي املدعــى عليــه األول علــى وجهــي‬\n      ‫وقــال واهلل ألقتلــك أنــت وأبــوك وش جابكــم ملزرعتنــا وابنــه وضــع‬\n      ‫إصبعــه عنــد عينــي وقــال ألرميــك بالســاح أنــت وأبــوك ثــم قــال واهلل‬\n      ‫إن مــا ذبحــت ابــوك مانــي رجــل ثــم قــال شــل حراثتــك وال أشــوفك هنــا‬\n      ‫ثــم انصــرف ملــا شــاهد أخوتــي هكــذا ادعــى املدعــي أطلــب مجازاتهــم‬\n      ‫وتأديبهــم وبســؤال املدعــى عليــه األول أجــاب قائــا مــا ذكــره املدعــي‬\n      ‫يف دعــواه ضــدي غيــر صحيــح فلــم أدخــل املزرعــة ولــم أهــدده هكــذا‬\n      ‫أجــاب وبســؤال املدعــى عليــه الثانــي أجــاب قائــا مــا ذكــره املدعــي‬\n\n‫‪377‬‬\n\f‫يف دعــواه ضــدي غيــر صحيــح فلــم أدخــل املزرعــة ولــم أهــدده هكــذا‬\n‫أجــاب وبســؤال املدعــي عــن البينــة قــال ليــس عنــدي بينــة وأطلــب ميــن‬\n‫املدعــى عليهمــا علــى نفــي دعــواي وبعــرض ذلــك علــى املدعــى عليهمــا‬\n‫قــاال ال مانــع عندنــا علــى أداء اليمــن علــى نفــي دعــواه ضدنــا فجــرى‬\n‫بيــان اليمــن التــي يحلفهــا املدعــى عليهمــا فوافقــا علــى ذلــك فأذنــت‬\n‫للمدعــى عليــه األول بــأداء اليمــن فحلــف قائــا واهلل إن مــا ذكــره‬\n‫املدعــي يف دعــواه ضــدي كلــه غيــر صحيــح هكــذا حلــف ثــم أذنــت‬\n‫للمدعــى عليــه الثانــي بــأداء اليمــن فحلــف قائــا واهلل إن مــا ذكــره‬\n‫املدعــي يف دعــواه ضــدي كلــه غيــر صحيــح هكــذا حلــف فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليهمــا أنكــرا مــا‬\n‫جــاء يف الدعــوى واملدعــي ليــس لديــه بينــة وطلــب ميــن املدعــى عليهمــا‬\n‫وأدى املدعــى عليهمــا اليمــن كمــا طلــب منهمــا ولقــول النبــي صلــى اهلل‬\n‫عليــه وســلم البينــة علــى املدعــي واليمــن علــى مــن أنكــر فقــد صرفــت‬\n‫النظــر عــن طلــب املدعــي مجــازاة املدعــى عليهمــا وأخليــت ســبيلهما هــذا‬\n‫مــا ظهــر لــي وبــه حكمــت واهلل أعلــم وأحكــم وبعــرض احلكــم علــى‬\n‫الطرفــن قــرر املدعــي قــرر عــدم القناعــة بهــذا احلكــم وطلــب رفعــه‬\n‫حملكمــة االســتئناف بــدون الئحــة اعتراضيــة وبعــرض احلكــم علــى‬\n‫املدعــى عليهمــا قــررا القناعــة بهــذا احلكــم وبهــذا انتهــت هــذه اجللســة‬\n‫يف متــام الســاعة احلاديــة عشــرة والنصــف وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/11/4‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة املختصــة‬\n‫بتدقيــق القضايــا اجلزائيــة األولــى مبحكمــة االســتئناف مبنطقــة حائــل‬\n‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بحائــل‬\n\n\n                                                                                   ‫‪378‬‬\n\f      ‫برقــم ‪ 342205090‬وتاريــخ ‪1434/11/11‬ه ـ واملقيــدة لدينــا برقــم‬\n      ‫‪ 342205090‬وتاريــخ ‪1434/11/12‬ه ـ واملرفــق بهــا الصــك الشــرعي‬\n      ‫الصــادر مــن فضيلــة الشــيخ‪ ).....(/‬القاضــي باحملكمــة اجلزائيــة بحائــل‬\n      ‫برقــم ‪ 34349902‬يف ‪1434/11/4‬ه بدعــوى (‪ ).....‬ضــد كل مــن‪/1 :‬‬\n      ‫(‪ ).....‬ســعودي اجلنســية ‪ ).....( /2‬ســعودي اجلنســية‪ .‬بشــأن دعــوى خاصــة‬\n      ‫(اعتــداء) وقــد تضمــن الصــك حكــم صاحــب الفضيلــة وفقــه اهلل علــى‬\n      ‫املدعــى عليهمــا علــى النحــو املفصــل يف الصــك املرفــق وبدراســة الصــك‬\n      ‫وصــورة ضبطــه وأوراق املعاملــة‪ :‬جــرت املصادقــة علــى مــا حكــم بــه‬\n      ‫فضيلتــه بالصــك املشــار إليــه‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                                  ‫وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪379‬‬\n\f                       ‫كشاف املوضوعات‬\n\n‫الصفحة‬                    ‫املوضوع‬                      ‫التصنيف‬     ‫م‬\n\n\n          ‫دعوى عامة ضد وافد عربي بالتشبه بالنساء‬\n  ‫‪5‬‬                                                     ‫شذوذ‬       ‫‪1‬‬\n                    ‫ووضع مساحيق نسائية‬\n\n\n         ‫دعوى عامة ضد مواطن بالتشبه بالنساء ونزع‬\n  ‫‪9‬‬      ‫شعر صدره ويديه واالستعداد ملمارسة الرذيلة‬      ‫شذوذ‬       ‫‪2‬‬\n           ‫واالعتداء على رجال هيئة األمر باملعروف‬\n\n\n           ‫دعوى عامة ضد مواطن بوضعه مساحيق‬\n  ‫‪17‬‬       ‫نسائية والتشبه بالنساء والعثور على صور‬       ‫شذوذ‬       ‫‪3‬‬\n                     ‫خليعة يف جواله‬\n\n\n         ‫دعوى عامة ضد وافدة عربية باخلروج من منزل‬\n  ‫‪27‬‬                                                   ‫تغيب فتاة‬   ‫‪4‬‬\n                       ‫زوجها دون إذنه‬\n\n\n          ‫دعوى عامة ضد امرأتني باالشتراك بإفساد‬\n            ‫وتخبيب زوجة غير سعودية على زوجها‬\n  ‫‪32‬‬                                                   ‫تغيب فتاة‬   ‫‪5‬‬\n           ‫وحتريضها على الهرب بأبنائها السعوديني‬\n            ‫القصر وعدم جتاوبهما أثناء االستجواب‬\n\n\n         ‫دعوى عامة ضد امرأة بالتغيب عن منزل ذويها‪،‬‬\n  ‫‪66‬‬                                                   ‫تغيب فتاة‬   ‫‪6‬‬\n                ‫والسفر دون محرم لغرض سيء‬\n\n\n           ‫دعوى عامة ضد شخص بإقامة عالقة غير‬\n  ‫‪71‬‬      ‫شرعية بفتاة وتغييبها عن منزل ذويها وإيوائه‬   ‫تغيب فتاة‬   ‫‪7‬‬\n                        ‫لها واالختالء بها‬\n\f‫الصفحة‬                   ‫املوضوع‬                    ‫التصنيف‬   ‫م‬\n\n\n         ‫دعوى عامة ضد وافد بالتحرش بالفتيات عن‬\n  ‫‪79‬‬     ‫طريق إمساك عضوه الذكري وإخراجه أمام‬         ‫حترش‬     ‫‪8‬‬\n                       ‫مدرسة البنات‬\n\n\n         ‫دعوى عامة ضد شخص مبحاولة إدخال حدث‬\n  ‫‪86‬‬                                                 ‫حترش‬     ‫‪9‬‬\n               ‫إلى منزله بالقوة لغرض سيء‬\n\n\n         ‫دعوى عامة ضد وافدين بالتحرش بفتاتني عند‬\n  ‫‪92‬‬      ‫دخولهما احملل ‪ ،‬حيث يقف الثاني للمراقبة‬    ‫حترش‬     ‫‪10‬‬\n                   ‫ليساعد األول يف التحرش‬\n\n\n           ‫دعوى عامة ضد شخص بالتحرش اجلنسي‬\n  ‫‪99‬‬      ‫بامرأة ؛ حيث طلب ملس يدها وكشف غطاء‬        ‫حترش‬     ‫‪11‬‬\n                     ‫وجهها فهربت‬\n\n\n           ‫دعوى عامة ضد شخص مبعاكسة امرأة‬\n ‫‪103‬‬                                                 ‫حترش‬     ‫‪12‬‬\n                    ‫وإزعاجها بالرسائل‬\n\n\n            ‫دعوى عامة ضد شخص بالتحرش بفتاة‬\n ‫‪108‬‬        ‫باإلمساك بها من كتفها وتقبيلها وملس‬      ‫حترش‬     ‫‪13‬‬\n                  ‫مؤخرتها بيده لغرض سيء‬\n\n\n         ‫دعوى عامة ضد شخصني مبعاكستهما للنساء‬\n ‫‪112‬‬      ‫يف األسواق حيث يوجد لدى كل واحد منهما‬      ‫حترش‬     ‫‪14‬‬\n             ‫قصاصة ورقية كتب عليها رقم هاتفه‬\n\n\n          ‫دعوى عامة ضد شخص بالتحرش بالطالبات‬\n ‫‪116‬‬                                                 ‫حترش‬     ‫‪15‬‬\n            ‫جنسيا ؛ مستغال عمله حارسا للمدرسة‬\n\f‫الصفحة‬                    ‫املوضوع‬                       ‫التصنيف‬    ‫م‬\n\n\n         ‫دعوى عامة ضد شخص بإقامة عالقة محرمة‬\n           ‫مع فتاة ال متت له بصلة شرعية ‪ ،‬واخللوة بها‬\n ‫‪122‬‬                                                     ‫حترش‬      ‫‪16‬‬\n          ‫وإزعاجها برسائل بذيئة وفاضحة وغير الئقة‬\n                           ‫والتغرير بها‬\n\n\n         ‫دعوى عامة ضد شخص بإقامة عالقة محرمة‬\n ‫‪130‬‬       ‫مع امرأة اشتكت من اعتداءاته ‪ ،‬وحيازة‬          ‫حترش‬      ‫‪17‬‬\n                ‫مقاطع جنسية وتصوير ذكره‬\n\n\n          ‫دعوى عامة ضد شخص مبعاكسته النساء‬\n ‫‪138‬‬                                                     ‫حترش‬      ‫‪18‬‬\n         ‫وحيازته جلوال يحوي عددا من املقاطع اجلنسية‬\n\n\n         ‫دعوى خاصة من شخص ضد امرأة اشتكته‬\n          ‫بأنه ال يصلي ال يف البيت وال يف املسجد ‪،‬‬\n ‫‪147‬‬                                                    ‫قذف زوجة‬   ‫‪19‬‬\n           ‫وميارس أعماال مشينة معها ومع غيرها ‪،‬‬\n                    ‫ويتعاطى املخدرات‬\n\n\n          ‫دعوى عامة ضد شخص بالتطاول على أئمة‬\n ‫‪153‬‬      ‫املساجد ووصفهم بالكالب التي تنبح وهم‬          ‫سب وشتم‬    ‫‪20‬‬\n                 ‫يقرؤون القران وقت الصالة‬\n\n\n           ‫دعوى عامة ضد شخصني ‪ ،‬فاألول بالسب‬\n                ‫ٍ‬\n          ‫مستوصف أثناء‬    ‫والشتم إلحدى العامالت يف‬\n ‫‪159‬‬                                                    ‫سب وشتم‬    ‫‪21‬‬\n           ‫تأديتها عملها وتهديدها ‪ ،‬والثاني بالتلفظ‬\n             ‫بألفاظ غير الئقة على إحدى العامالت‬\n\n\n         ‫دعوى عامة ضد شخص بالتلفظ بألفاظ بذيئة‬\n ‫‪167‬‬     ‫على الرسول صلى اهلل عليه وسلم ‪ ،‬ومالحقته‬       ‫سب وشتم‬    ‫‪22‬‬\n         ‫للمجني عليه وصدمه بسيارته وتهديده بالقتل‬\n\f‫الصفحة‬                    ‫املوضوع‬                     ‫التصنيف‬       ‫م‬\n\n\n          ‫بسبه لرجل وقذفه‬\n                      ‫دعوى عامة ضد شخص ّ‬\n ‫‪170‬‬                                                  ‫سب وشتم‬       ‫‪23‬‬\n          ‫أثناء تأديته مهام عمله يف صيدلية مستشفى‬\n\n\n           ‫دعوى خاصة من شخص ضد رجل لتقدميه‬\n ‫‪177‬‬     ‫شكوى كيدية ضده فأحيل للتحقيق ولم يثبت‬        ‫إيذاء الغير‬   ‫‪24‬‬\n                    ‫حينها ّبينة على كالمه‬\n\n\n           ‫دعوى خاصة من وكيل مدعية ضد امرأة‬\n ‫‪181‬‬                                                  ‫إيذاء الغير‬   ‫‪25‬‬\n            ‫قامت بصفع موكلته بيدها على وجهها‬\n\n\n             ‫مدع ضد رجل‬‫دعوى خاصة من وكيل ٍ‬\n         ‫باالعتداء على موكله بضربه بآلة حادة (مفتاح‬\n ‫‪183‬‬                                                  ‫إيذاء الغير‬   ‫‪26‬‬\n          ‫معدني) على رأسه مما جنم عنه جرح قطعي‬\n                        ‫سطحي يف رأسه‬\n\n\n          ‫دعوى خاصة من شخص ضد رئيس حترير‬\n         ‫إحدى الصحف لنشره حكما قضائيا يخصه‬\n ‫‪188‬‬                                                  ‫إيذاء الغير‬   ‫‪27‬‬\n           ‫مما تسبب بضرر مادي حلق به من تشهير‬\n                     ‫وإضرار بسمعته‬\n\n\n         ‫دعوى خاصة ضد مدعى عليهم قاموا باستغالل‬\n          ‫السلطة املمنوحة لهم يف جهة عملهم بكتابة‬\n ‫‪196‬‬                                                  ‫إيذاء الغير‬   ‫‪28‬‬\n           ‫خطاب إلى الوزير يتضمن معلومات مخالفة‬\n                       ‫ملجريات التحقيق‬\n\n\n            ‫مدع ضد شخص‬ ‫دعوى خاصة من وكيل ٍ‬\n ‫‪201‬‬     ‫بتلفظه على موكله يف قضية حضانة بينه وبني‬     ‫إيذاء الغير‬   ‫‪29‬‬\n                           ‫زوجته‬\n\f‫الصفحة‬                    ‫املوضوع‬                     ‫التصنيف‬       ‫م‬\n\n\n          ‫دعوى خاصة ضد وافد عربي لتطاوله على‬\n ‫‪209‬‬      ‫املدعي بالكالم ومالحقته واضطراره إلى‬        ‫إيذاء الغير‬   ‫‪30‬‬\n         ‫ضيق لسيارته حتى أجبروه على الوقوف‬\n                                       ‫ٍ‬   ‫طريق‬\n\n\n         ‫دعوى خاصة ضد شخص تلفظ بألفاظ بذيئة‬\n ‫‪213‬‬      ‫ثم تشابك مع املدعي باأليدي‪ ،‬وضربه بيده‬      ‫إيذاء الغير‬   ‫‪31‬‬\n             ‫وبالعقال مما تسبب يف إصابته بجروح‬\n\n\n         ‫دعوى خاصة ضد شخص قدم بالغا يف مركز‬\n ‫‪222‬‬      ‫الشرطة بأنه أشهر السالح يف وجهه فأُوقِ َف‬   ‫إيذاء الغير‬   ‫‪32‬‬\n                    ‫على إثر ذلك ملدة يوم واحد‬\n\n\n           ‫سبه وتلفظ عليه‬\n                       ‫دعوى خاصة ضد شخص َّ‬\n ‫‪227‬‬                                                  ‫إيذاء الغير‬   ‫‪33‬‬\n                  ‫بألفاظ بذيئة ال يذكرها‬\n\n\n          ‫دعوى خاصة ضد شخص ضربه على وجهه‬\n ‫‪232‬‬                                                  ‫إيذاء الغير‬   ‫‪34‬‬\n                         ‫بيده‬\n\n\n          ‫دعوى خاصة ضد شخص ضربه على ركبته‬\n ‫‪238‬‬                                                  ‫إيذاء الغير‬   ‫‪35‬‬\n          ‫وأحدث بها التواء شديدا أثرت على احلركة‬\n\n\n          ‫دعوى خاصة بوالية عن ابن ضد ُم َعلِّم ضرب‬\n ‫‪243‬‬     ‫االبن على رأسه بيده ‪ ،‬كما حاول ضرب األب‬      ‫إيذاء الغير‬   ‫‪36‬‬\n               ‫أيضا متلفظا عليه مهددا بالقتل‬\n\n\n           ‫دعوى خاصة ضد امرأة بسبها واتهامها له‬\n ‫‪249‬‬                                                  ‫إيذاء الغير‬   ‫‪37‬‬\n                        ‫بالنفاق والكذب‬\n\f‫الصفحة‬                   ‫املوضوع‬                    ‫التصنيف‬       ‫م‬\n\n\n         ‫دعوى خاصة ضد شخص حرق سيارة املدعي‬\n ‫‪253‬‬                                                ‫إيذاء الغير‬   ‫‪38‬‬\n           ‫دون أي دليل مما تسبب بتشويه سمعته‬\n\n\n           ‫مدع ضد ابن اخته بضربه بيده‬‫دعوى من ٍ‬\n         ‫مما تسبب يف إصابته بكدمة يف الشفة العليا‬\n ‫‪261‬‬                                                ‫إيذاء الغير‬   ‫‪39‬‬\n         ‫وسحجة يف الركبة اليسرى ‪ ،‬مع تهديده عن‬\n                      ‫طريق رسائل اجلوال‬\n\n\n          ‫دعوى خاصة ضد شخص طرد املدعي من‬\n ‫‪268‬‬                                                ‫إيذاء الغير‬   ‫‪40‬‬\n              ‫العمل لديه إثر خالفات بينهما‬\n\n\n           ‫دعوى خاصة ضد شخص ضرب املدعي‬\n ‫‪273‬‬                                                ‫إيذاء الغير‬   ‫‪41‬‬\n           ‫بالعقال ولعن والديه بعد مشادة بينهما‬\n\n\n          ‫شوه سمعته وذلك‬\n                      ‫دعوى خاصة ضد شخص ّ‬\n ‫‪278‬‬      ‫باحلديث عنه بني املدرسني على أنه صاحب‬     ‫إيذاء الغير‬   ‫‪42‬‬\n                ‫فكر ضال وال والء له للوطن‬\n\n\n         ‫مدع ضد شخص رفع‬  ‫دعوى خاصة من وكيل ٍ‬\n ‫‪288‬‬     ‫شكوى كيدية ضد موكله اتهمه أنه هدده‬         ‫إيذاء الغير‬   ‫‪43‬‬\n                    ‫فحول للتحقيق‬\n                             ‫بالقتل ِّ‬\n\n\n         ‫دعوى خاصة ضد شخص اعتدى عليه بالتلفظ‬\n ‫‪302‬‬                                                ‫إيذاء الغير‬   ‫‪44‬‬\n                  ‫عليه وتصويره خلالف بينهما‬\n\n\n          ‫دعوى خاصة ضد شخص دخل بيته وغرفة‬\n ‫‪308‬‬                                                ‫إيذاء الغير‬   ‫‪45‬‬\n                     ‫زوجته لغرض سيء‬\n\f‫الصفحة‬                    ‫املوضوع‬                      ‫التصنيف‬       ‫م‬\n\n\n         ‫دعوى خاصة ضد شخص اعتدى عليه بالضرب‬\n ‫‪312‬‬     ‫مما تسبب يف إصابته بكدمات يف الشفة العليا‬     ‫إيذاء الغير‬   ‫‪46‬‬\n           ‫وحتت الذقن وحول الرقبة والكتف األيسر‬\n\n\n         ‫دعوى خاصة ضد شخص أرسل له رسالة جوال‬\n ‫‪316‬‬                                                   ‫إيذاء الغير‬   ‫‪47‬‬\n                        ‫تتضمن شتمه‬\n\n\n         ‫دعوى خاصة ضد شخص اعتدى عليه بالضرب‬\n           ‫مما تسبب يف إصابته بكدمات بالوجه‬\n ‫‪319‬‬                                                   ‫إيذاء الغير‬   ‫‪48‬‬\n         ‫والركبتني وسجحات بالظهر وحتركت بعض‬\n                ‫أسنانه مع نزيف يسير بالفم‬\n\n\n          ‫سبه ولعن والديه ‪،‬‬\n                         ‫دعوى خاصة ضد شخص ّ‬\n ‫‪323‬‬                                                   ‫إيذاء الغير‬   ‫‪49‬‬\n                    ‫وضايقه وطارده بالسيارة‬\n\n\n            ‫دعوى من مدعية ضد شخص تلفظ عليها‬\n ‫‪326‬‬          ‫واتهمها يف شرفها حيث ذكر أن أحد‬          ‫إيذاء الغير‬   ‫‪50‬‬\n          ‫األشخاص يكثر الدخول واخلروج إلى شقتها‬\n\n\n         ‫سبه وتلفظ عليه أثناء‬\n                           ‫دعوى خاصة ضد شخص ّ‬\n ‫‪330‬‬                                                   ‫إيذاء الغير‬   ‫‪51‬‬\n                  ‫ترافعهما أمام إحدى احملاكم‬\n\n\n           ‫دعوى من وكيل مدعية ضد شخص قذف‬\n ‫‪336‬‬                                                   ‫إيذاء الغير‬   ‫‪52‬‬\n             ‫موكلته ووصفها بالكالم البذيء‬\n\n\n           ‫دعوى خاصة ضد امرأة قدمت ضده بالغا‬\n ‫‪343‬‬      ‫لهيئة األمر باملعروف والنهي عن املنكر بغير‬   ‫إيذاء الغير‬   ‫‪53‬‬\n             ‫حق فقبض عليه وأوقف ملدة يوم واحد‬\n\f‫الصفحة‬                    ‫املوضوع‬                     ‫التصنيف‬       ‫م‬\n\n\n         ‫دعوى خاصة ضد شخص تلفظ عليه بقول ‪ :‬يا‬\n ‫‪347‬‬                                                  ‫إيذاء الغير‬   ‫‪54‬‬\n                ‫فاجر ‪ .‬ودعا عليه باملوت والزوال‬\n\n\n         ‫مدع ضد شخص سبه وشتمه أمام‬‫دعوى من ٍ‬\n ‫‪351‬‬                                                  ‫إيذاء الغير‬   ‫‪55‬‬\n                  ‫سكنه ‪ ،‬وحاول ضربه‬\n\n\n           ‫مدع ضد شخص سبه واتهمه‬  ‫دعوى من ٍ‬\n ‫‪355‬‬        ‫بالسكر أمام جمع من الناس يف دائرة‬         ‫إيذاء الغير‬   ‫‪56‬‬\n                          ‫حكومية‬\n\n\n            ‫مدع ضد شخص قذفه بالسب‬    ‫دعوى من ٍ‬\n ‫‪359‬‬        ‫والشتم قائال ‪ :‬أنتم أهل اللحى مجرمني‬      ‫إيذاء الغير‬   ‫‪57‬‬\n         ‫ونصابني ودجالني ومنافقني ثم هدده باالغتيال‬\n\n\n         ‫مدع ضد شخص قذفه وسبه وشتمه‬   ‫دعوى من ٍ‬\n ‫‪363‬‬                                                  ‫إيذاء الغير‬   ‫‪58‬‬\n             ‫يف الدائرة احلكومية التي يعمالن بها‬\n\n\n           ‫مدع ضد شخص اعتدى‬ ‫دعوى من وكيل ٍ‬\n ‫‪368‬‬      ‫على موكله بالضرب مما تسبب يف إصابته‬         ‫إيذاء الغير‬   ‫‪59‬‬\n          ‫بكدمات يف الوجه وكسر لبعض األسنان‬\n\n\n          ‫دعوى من مدعية ضد شخص سبها وشتمها‬\n ‫‪371‬‬                                                  ‫إيذاء الغير‬   ‫‪60‬‬\n               ‫وعيرها بأن زواجها غير شرعي‬\n\n\n         ‫مدع ضد شخصني ‪ :‬أحدهما ضربه‬    ‫دعوى من ٍ‬\n ‫‪376‬‬       ‫واآلخ ِر ساعده‬\n                    ‫َ‬     ‫‪،‬‬ ‫بالقتل‬ ‫وهدده‬ ‫على وجهه‬     ‫إيذاء الغير‬   ‫‪61‬‬\n                          ‫وتعاون معه‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":376,"source_page_end":387,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"31119c4814738e625752bccf0545f7414a32c06d120a66db7e99f4196a86e87e","normalized_text_hash":"26c7a7835fe00eb724d752b93d8cfc9e78da6ebdc2c8c0c0d27287eae0e63c83","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p376-34349902"},{"id":"6cfb8d16-a041-527d-bc60-3b8af31cd35d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب مسكر -حيازة بقصد االستعمال -االجتماع على مفسدة -التعزير للتهمة .","document_number":"34351747","case_number":"3097","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية على املعاملة املقيدة لدى المحكمة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/05","year":"1434","subject":"مسكر -شرب مسكر -حيازة بقصد االستعمال -االجتماع على مفسدة -التعزير للتهمة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫رقم الصك‪ 34351747 :‬تاريخه‪1434/11/05 :‬هـ‬\n                            ‫رقم الدعوى‪3097 :‬‬\n                  ‫رقم قرار التصديق من محكمة‬\n     ‫االستئناف‪ 34381427:‬تاريخه‪1434/12/18:‬هـ‬\n\n\n     ‫مســكر ‪ -‬شــرب مســكر ‪ -‬حيــازة بقصــد االســتعمال ‪ -‬االجتمــاع علــى‬\n                                                 ‫مفســدة ‪ -‬التعزيــر للتهمــة ‪.‬‬\n\n\n\n\n     ‫لعــن رســول اهلل صلــى اهلل عليــه وســلم يف اخلمــر ثمانيــة ( شــاربها‬\n     ‫وســاقيها وحاملهــا واحملمولــة إليــه وعاصرهــا ومعتصرهــا وبائعهــا‬\n                                                            ‫وآكل ثمنهــا ) ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وحيازتــه لــه‬\n     ‫بقصــد االســتعمال ‪،‬واالجتمــاع علــى مفســدة وطلــب إثبــات مــا أســند‬\n     ‫إليــه ‪،‬واحلكــم عليــه بحــد املســكر وعقوبــة لقــاء حيــازة املســكر‬\n     ‫واالجتمــاع علــى مفســدة ‪،‬حيــث مت القبــض عليــه مــن قبــل أعضــاء هيئــة‬\n     ‫األمــر باملعــروف والنهــي عــن املنكــر بشــقة وبرفقــة حــدث يلبــس مالبس‬\n     ‫ضيقــة ‪،‬واتضــح أنــه بحالــة غيــر طبيعيــة وباستشــمامه تبــن انبعــاث‬\n     ‫رائحــة املســكر مــن أنفاســه ‪،‬وأثبــت التقريــر الكيميائــي الشــرعي‬\n     ‫إيجابيــة العينــة ملــادة الكحــول اإليثيلــي ‪،‬وصــادق املدعــى عليــه علــى‬\n     ‫دعــوى املدعــي العــام ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بجلــده‬\n     ‫ثمانــن جلــده حــد املســكر دفعــة واحــدة وســجنه ســبعة أيــام ‪،‬ولتوجــه‬\n\n‫‪5‬‬\n\f‫التهمــة للمدعــى عليــه باالجتمــاع علــى مفســدة تعزيــره بالســجن ثالثــة‬\n‫أشــهر وجلــده ســبعني جلــدة مفرقــة علــى دفعتــن ‪،‬وقنــع املدعــى عليــه‬\n‫‪،‬وصــدق احلكــم مــن محكمــة‬  ‫‪،‬واعتــرض املدعــي العــام بــدون الئحــة ُ‬\n                                                               ‫االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n‫‪ .....‬القاضــي باحملكمــة اجلزائيــة باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة يف محافظــة اخلبــر برقــم ‪3097‬‬\n‫وتاريــخ ‪ 1430/08/19‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3010275‬وتاريــخ‬\n‫‪ 1430/08/19‬ه ـ ففــي يــوم األربعــاء املوافق‪ 1434/11/05‬هـ افتتحت‬\n‫اجللســة الســاعة ‪ 09 : 00‬وفيهــا قــدم املدعــي العــام ‪.....‬الئحــة دعــوى‬\n‫ا فيهــا انــه‬ ‫عامــة ضــد م ‪ .....‬ســعودي بالســجل املدنــي رقــم (‪ ).....‬قائ ـ ً‬\n‫بتاريــخ ‪1429/1/28‬ه ـ مت القبــض علــى املدعــى عليــه املذكــور باخلبــر‬\n‫اجلنوبيــة داخــل شــقة مــن قبــل رجــال هيئــة األمــر باملعــروف والنهــي عــن‬\n‫املنكــر رفــق آخــر (فــرزت لــه أوراق مســتقلة) واتضــح أنــه بحالــة غيــر‬\n‫طبيعيــة اشــتباه (ســكر) وباستشــمامه تبــن انبعــاث رائحــة املســكر‬\n‫مــن أنفاســه وقــد اثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪).....‬‬\n‫ايجابيــة مــا ضبــط مــع املدعــى عليــه ملــادة الكحــول االيثيلــي وبنســبة‬\n‫مســكرة وباســتجوابه اعتــرف بشــرب املســكر وانــه احضــره مــن‬\n‫شــخص بحرينــي ال يعرفــه وقــد أســفر التحقيــق معــه عــن توجيــه االتهــام‬\n‫للمدعــى عليــه بشــرب املســكر وحيازتــه بقصــد االســتعمال الشــخصي‬\n‫واالجتمــاع علــى مفســدة وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه‬\n\n                                                                                         ‫‪6‬‬\n\f    ‫علــى ســوابق مســجلة وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل‬\n    ‫أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب‬\n    ‫إثبــات مــا أســند إليــه واحلكــم عليــه بحــد املســكر لقــاء شــربه لــه كمــا‬\n    ‫أطلــب احلكــم عليــه بعقوبــة تزجــره وتــردع غيــره لقــاء حيازتــه للمســكر‬\n    ‫واجتماعــه مــع آخــر علــى مفســدة هــذه دعــواي وبســؤال املدعــى عليــه‬\n    ‫عــن الدعــوى أجــاب بقولــه الصحيــح أنــه مت القبــض علــي يف تاريــخ‬\n    ‫‪1429/1/28‬ه ـ عنــد منتصــف الليــل وأنــا متواجــد داخــل شــقه مفروشــة‬\n    ‫يف حــي ‪.....‬يف اخلبــر وكنــت أنــا يف حالــة ســكر حيــث إنــي شــربت‬\n    ‫املســكر وقــد كان معــي كأس زجاجــي يحتــوي علــى املســكر وهــو‬\n    ‫يعــود لــي وكنــت أنــوي شــربه وكان معــي يف نفــس الشــقة ‪.....‬ويبلــغ مــن‬\n    ‫العمــر يف ذلــك الوقــت حوالــي ســبعة عشــر عامـ ًا فأنــا أكبــر منــه بنحــو‬\n    ‫تســع أعــوام وهــو مــن قــام بدعوتــي إلــى الشــقة فهــو لديــه شــذوذ وكان‬\n    ‫وقــت القبــض علينــا يلبــس مالبــس ضيقــة وقــد وضــع الكحــل يف عينيــه‬\n    ‫ولــم يشــرب هــو املســكر وكنــا لوحدنــا يف الشــقة ولــم يحصــل بيننــا‬\n    ‫أي شــيء وتعرفــت عليــه كونــه جــار لنــا يف نفــس احلــارة وأنــا نــادم علــى‬\n    ‫فعلــي وتائــب إلــى اهلل تعالــى هكــذا أجــاب بعــد ذلــك جــرى الــر جــوع‬\n    ‫إلــى اللفــة رقــم (‪ )15‬وتضمنــت التقريــر الكيمــاوي الشــرعي وهــو‬\n    ‫كمــا ذكــر املدعــي العــام يف دعــواه كمــا جــرى الرجــوع إلــى اللفــة‬\n    ‫رقــم (‪ )20‬وتضمنــت محضــر القبــض ويظهــر منــه أن املضبــوط كأس‬\n    ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬ ‫زجاجــي بــه الربــع مــن اخلمــر فبنـ ً‬\n    ‫وحيــث أقــر املدعــى عليــه بشــرب املســكر وحيازتــه بقصــد الشــرب‬\n    ‫وهــذا مــن كبائــر الذنــوب فقــد لعــن رســول اهلل صلــى اهلل عليــه وســلم‬\n    ‫يف اخلمــر ثمانيــة (شــاربها وســاقيها وحاملهــا واحملمولــة إليــه وعاصرهــا‬\n\n\n‫‪7‬‬\n\f‫ومعتصرهــا وبائعهــا واكل ثمنهــا) واللعــن ال يكــون إال علــى كبيــرة‬\n‫مــن كبائــر الذنــوب وحيــث أقــر املدعــى عليــه بأنــه قبــض عليــه ومعــه‬\n‫حــدث قــد وضــع الكحــل يف عينيــه ويلبــس مالبــس ضيقــه وهــذا يوجــه‬\n‫التهمــة للمدعــى عليــه باالجتمــاع علــى املفســدة لــذا فقــد قــررت مــا يلــي‬\n‫أو ًال ثبــت لــدي شــرب املدعــى عليــه للمســكر وقــررت أن يجلــد لقــاء‬\n‫ذلــك حــد املســكر ثمانــن جلــده دفعــة واحــدة ثاني ـ ًا ثبــت لــدي حيــازة‬\n‫املدعــى عليــه كأس زجاجــي يحتــوي علــى املســكر بقصــد الشــرب‬\n‫وقــررت تعزيــر املدعــى عليــه لقــاء ذلــك بســجنه مــدة ســبعة أيــام ثالث ـ ًا‬\n‫توجــه التهمــه للمدعــى عليــه باالجتمــاع علــى مفســدة وقــررت تعزيــره‬\n‫لقــاء ذلــك بســجنه مــدة ثالثــة أشــهر وجلــده ســبعني جلــده علــى دفعتــن‬\n‫متســاويتني بينهمــا مــدة ال تقــل عــن عشــرة أيــام وبــن جلــد احلــد وجلــد‬\n‫التعزيــر مــدة ال تقــل عــن عشــرة أيــام وبذلــك يكــون ســجن املدعــى‬\n‫عليــه هــو ثالثــة أشــهر وســبعة أيــام اعتبــار ًا مــن تاريــخ إيقافــه ومبــا تقــدم‬\n‫حكمــت وبعــرض احلكــم قنــع املدعــى عليــه ولــم يقنــع املدعــي العــام‬\n‫مكتفيـ ًا مبــا قــدم يف الئحــة الدعــوى وأقفلــت اجللســة الســاعة العاشــرة‬\n                                             ‫وصلــى اهلل وســلم علــى نبينــا محمــد‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/2589973‬ج‪ 2‬وتاريــخ ‪1434/11/12‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم‬\n‫‪ 30/10275‬وتاريــخ ‪1434/11/9‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪..... /‬املســجل برقــم ‪34351747‬‬\n‫وتاريــخ ‪1434/11/5‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪...../‬ي يف‬\n\n\n                                                                                            ‫‪8‬‬\n\f    ‫قضيــة مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n    ‫ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n    ‫املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                    ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/12/18‬ه ـ ‪.‬‬\n\n\n\n\n‫‪9‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":5,"source_page_end":9,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7b024e4a02df3358ed894c649fa3f8553df0c203c010e0e69a54a826b467f0e0","normalized_text_hash":"296fb5d3ebd7092ee1fffce6cad23993a62629c6f01edc770686c2f566f51267","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p5-34351747"},{"id":"dd18f0b7-4779-517a-82f1-e6c654745460","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب مسكر -احلدود تدرأ بالشبهات -رد الدعوى -عدم ثبوت االدعاء -التعزير باجللد للشبهة .","document_number":"34166404","case_number":"3797","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/18","year":"1434","subject":"مسكر -شرب مسكر -احلدود تدرأ بالشبهات -رد الدعوى -عدم ثبوت االدعاء -التعزير باجللد للشبهة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34166404 :‬تاريخه‪1434/3/18 :‬هـ‬\n                        ‫رقم الدعوى ‪3797:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34214644‬تاريخه‪1434/05/18:‬هـ‬\n\n\n ‫مســكر ‪ -‬شــرب مســكر ‪ -‬احلــدود تــدرأ بالشــبهات ‪ -‬رد الدعــوى‪ -‬عــدم‬\n                         ‫ثبــوت االدعــاء ‪ -‬التعزيــر باجللــد للشــبهة ‪.‬‬\n\n\n\n\n ‫مــا نــص عليــه البهوتــي يف كشــاف القنــاع ‪ ( 101/14‬وال يحــد بوجــود‬\n                 ‫رائحــة اخلمــر منــه واحلــد يــدرأ بالشــبهة لكــن يعــزر ) ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وطلــب إثبــات‬\n ‫مــا أســند إليــه واحلكــم عليــه بحــد شــرب املســكر ‪،‬حيــث لوحــظ‬\n ‫املدعــى عليــه بحالــة غيــر طبيعيــة فتبــن أنــه بحالــة ســكر وباستشــمامه‬\n ‫تبــن انبعــاث رائحــة املســكر مــن أنفاســه وأنكــر املدعــى عليــه شــرب‬\n ‫املســكر ودفــع بخروجــه مــن املستشــفى وشــربه للــدواء قبــل القبــض‬\n ‫عليــه وجــرى الكتابــة للمستشــفى فصــادق علــى دفــع املدعــى عليــه وأنــه‬\n ‫راجعهــم ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بــرد دعــوى املدعــي‬\n ‫العــام باملطالبــة بإقامــة حــد املســكر لعــدم ثبوتــه وتعزيــر املدعــى عليــه‬\n ‫للشــبهة بشــرب املســكر بجلــده ثالثــن جلــدة دفعــة واحــدة واعتــرض‬\n ‫‪،‬وصــدق‬\n       ‫املدعــى عليــه بالئحــة اعتراضيــة واملدعــي العــام بــدون الئحــة ُ‬\n                                          ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n                                                                                      ‫‪10‬‬\n\f     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n     ‫‪ .....‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة مــن‬\n     ‫هيئــة التحقيــق واالدعــاء العــام واملقيــدة لــدى احملكمة برقــم ‪3116113‬‬\n     ‫وتاريــخ ‪1431/8/14‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫اجلزائيــة بالدمــام برقــم ‪ 3797‬وتاريــخ ‪1431/8/14‬ه ـ افتتحــت اجللســة‬\n     ‫يف يــوم الثالثــاء ‪1433/6/17‬ه ـ الســاعة التاســعة والنصــف وفيهــا قــدم‬\n     ‫ا فيهــا بصفتــي مدعيـ ًا عام ًا بدائــرة االدعاء‬\n                                                     ‫املدعــي العــام ‪.....‬دعــواه قائـ ً‬\n     ‫العــام لفــرع املنطقــة الشــرقية أدعــي علــى‪..... /‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم (‪ ).....‬حيــث إنــه باالطــاع علــى محضــر تنفيــذ‬\n     ‫املهمــة املعــد مــن قبــل رجــال الضبــط اجلنائــي بالدوريــات األمنيــة بالدمــام‬\n     ‫تبــن أنــه يف يــوم األربعــاء ‪1431/7/27‬ه ـ لوحــظ املدعــى عليــه يف حالــة‬\n     ‫غيــر طبيعيــة وبالتأكــد منــه تبــن أنــه بحالــة ســكر وباستشــمامه‬\n     ‫تبــن انبعــاث رائحــة املســكر مــن أنفاســه وباســتجواب املدعــى عليــه‬\n     ‫أنكــر شــرب املســكر وأنكــر أن تكــون رائحــة املســكر قــد انبعثــت‬\n     ‫مــن أنفاســه وأفــاد بأنــه كان قــد خــرج لتــوه مــن أحــد العمليــات وأن‬\n     ‫هــذا الســبب يف عــدم متاســكه وأضــاف أن الرائحــة املنبعثــة منــه هــي‬\n     ‫رائحــة الــدواء الــذي يســتخدمه وانتهــى التحقيــق إلــى اتهــام املدعــى‬\n     ‫عليــه بشــرب املســكر وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬محضــر‬\n     ‫تنفيــذ املهمــة املرفــق علــى اللفــة رقــم (‪ -2 )2‬محضــر االستشــمام املنــوه‬\n     ‫عنــه واملــدون علــى الصفحــة رقــم (‪ )4‬مــن ملــف التحقيــق املرفــق لفــة‬\n     ‫رقــم (‪ )1‬وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســوابق وحيــث إن‬\n     ‫مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل‬\n‫‪11‬‬\n\f‫محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات إدانتــه مبــا نســب إليــه‬\n‫واحلكــم عليــه بحــد شــرب املســكر هكــذا ادعــى وبعــرض الدعــوى‬\n‫ا مــا ذكــره املدعــي العــام مــن قيامــي‬  ‫علــى املدعــى عليــه أجــاب قائ ـ ً‬\n‫بشــرب املســكر فذلــك غيــر صحيــح والصحيــح أننــي كنــت خرجــت‬\n‫مــن املستشــفى يف ذلــك اليــوم بعدمــا قمــت بعمليــة لــدى املستشــفى‬\n‫(‪)........‬ولــم أقــم بــاألكل وكنــت أعــرج يف املشــي وشــاهدني رجــال‬\n‫األمــن فظنــوا أننــي بحالــة ســكر وقبضــوا علــي هكــذا أجــاب وبعــرض‬\n‫ذلــك علــى املدعــي العــام قــال مــا ذكــره املدعــى عليــه غيــر صحيــح‬\n‫والصحيــح مــا ذكرتــه يف دعــواي هكــذا أجــاب وبســؤال املدعــى‬\n‫عليــه البينــة علــى مــا ذكــره قــال أطلــب الكتابــة للمستشــفى (‪).........‬‬\n‫للتأكــد مــن ذلــك هكــذا أجــاب ويف جلســة أخــرى حضــر املدعــي العــام‬\n‫ولــم يحضــر املدعــى عليــه وقــد كنــا كتبنــا خطــاب للمستشــفى فوردنــا‬\n‫اخلطــاب مــن مديــر مجمــع الدمــام الطبــي برقــم ‪.....‬يف ‪1433/7/27‬ه ـ‬\n‫ونصــه مــا يلــي ( بعــد البحــث يف احلاســب اآللــي لدينــا تبــن أن املدعــى‬\n‫عليــه راجــع قســم اإلســعاف فقــط منــذ ســنتني ) ثــم جــرى ســؤال املدعــي‬\n‫العــام البينــة علــى دعــواه فقــال أطلــب الرجــوع إلــى املعاملــة هكــذا‬\n‫أجــاب ويف يــوم األربعــاء ‪1434/3/18‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n‫الطرفــان ثــم جــرى الرجــوع إلــى املعاملــة فوجــدت علــى لفــة رقــم (‪ )1‬ص‬\n‫(‪ )6‬محضــر استشــمام املتضمــن طبــق مــا ذكــر املدعــي العــام يف دعــواه‬\n‫ـاء علــى مــا تقــدم مــن دعــوى املدعــي العــام وإجابــة املدعــى عليــه‬ ‫فبنـ ً‬\n‫ـاء محضــر االستشــمام ومبــا أن املدعــى عليــه قــد‬   ‫وإنــكاره للدعــوى وبنـ ً‬\n‫راجــع املستشــفى قبــل القبــض عليــه وهــذه شــبهة ومبــا أن احلــدود تــدرأ‬\n‫بالشــبهات ونظــر ًا ملــا ذكــره الفقهــاء ومــن ذلــك مــا نــص عليــه البهوتــي‬\n\n\n                                                                                     ‫‪12‬‬\n\f     ‫يف كشــاف القنــاع (‪ ).....‬بقولــه ( وال يحــد بوجــود رائحــة اخلمــر منــه‬\n     ‫واحلــد يــدرأ بالشــبهة لكــن يعــزر ) لــذا كلــه لــم تثبــت لــدي إدانــة املدعى‬\n     ‫عليــه وقــررت اآلتــي‪ :‬أوالً‪ :‬رد دعــوى املدعــي العــام باملطالبــة بإقامــة حــد‬\n     ‫املســكر علــى املدعــى عليــه لعــدم ثبوتهــا‪ .‬ثاني ـاً‪ :‬تعزيــر املدعــى عليــه‬\n     ‫باجللــد ثالثــن جلــدة دفعــة واحــدة لقــاء شــبهة شــرب املســكر وبــكل‬\n     ‫مــا تقــدم حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n     ‫عــدم القناعــة باحلكــم وطلــب االســتئناف بالئحــة يقدمهــا فأفهمتــه بأنه‬\n     ‫ســوف يجــري تســليمه بعــد قليــل نســخة مــن احلكــم ليقــدم اعتراضــه‬\n     ‫خــال ثالثــن يوم ـ ًا يكــون حقــه يف االســتئناف بعدهــا ســاقطا ففهــم‬\n     ‫ذلــك وأمــا املدعــي العــام فقــرر االعتــراض علــى احلكــم واالكتفــاء‬\n     ‫بالئحــة الدعــوى العامــة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                                                     ‫محمــد‪ .‬حــرر يف ‪1434/3/18‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n     ‫لــدى احملكمــة برقــم ‪/34/1086643‬ج‪ 2‬وتاريــخ ‪1434/5/4‬ه ـ الواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم ‪31/16113‬‬\n     ‫وتاريــخ ‪1434/4/29‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n     ‫القاضــي باحملكمــة الشيخ‪...../‬املســجل برقــم ‪ 34166404‬وتاريــخ‬\n     ‫‪1434/3/18‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ ...../‬يف قضيــة‬\n     ‫مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n     ‫فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n     ‫علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                    ‫وســلم‪ .‬حــرر يف ‪1434/5/18‬ه ـ ‪.‬‬\n\n\n‫‪13‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":10,"source_page_end":13,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"62a644ecbc85c49a01acb308f69130f164e293ef02c7102fce6ae9879874be0e","normalized_text_hash":"a42b539a04e381cabab4844206e32f9c7944c97a8d7eb56c79d800876e5ad2c8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p10-34166404"},{"id":"4b75080d-1a3c-5558-9331-a743f08dcee1","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب مسكر -حيازة بقصد الشرب -قيادة السيارة حتت تأثير املسكر -ال يحد حد املسكر بالرائحة -التعزير باجللد","document_number":"3418751","case_number":"5036","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/20","year":"1434","subject":"مسكر -شرب مسكر -حيازة بقصد الشرب -قيادة السيارة حتت تأثير املسكر -ال يحد حد املسكر بالرائحة -التعزير باجللد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3418751 :‬تاريخه‪1434/1/20:‬هـ‬\n                      ‫رقم الدعوى‪5036 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 3438319‬تاريخه‪1434/02/16 :‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب مســكر ‪ -‬حيــازة بقصــد الشــرب ‪ -‬قيــادة الســيارة حتــت‬\n‫تأثيــر املســكر ‪ -‬ال يحــد حــد املســكر بالرائحــة ‪ -‬التعزيــر باجللــد‬\n                                                              ‫للشــبهة ‪.‬‬\n\n\n\n\n‫مــا نــص عليــه البهوتــي يف كشــاف القنــاع ‪ ( 101/14‬وال يحــد بوجــود‬\n                ‫رائحــة اخلمــر منــه واحلــد يــدرأ بالشــبهة لكــن يعــزر ) ‪.‬‬\n\n\n\n\n‫دعــوى املدعــي العــام ضــد املدعــى عليهــم ثالثــة بقيامهــم بشــرب‬\n‫املســكر وقيــادة الثانــي الســيارة وهــو حتــت تأثيــر املســكر وحيــازة‬\n‫األول للمســكر بقصــد الشــرب وطلــب إثبــات مــا أســند إليهــم واحلكــم‬\n‫عليهــم بحــد املســكر وتعزيــر األول للحيــازة وإثبــات إدانــة الثانــي بقيــادة‬\n‫الســيارة حتــت تأثيــر املســكر وعقابــه عائــد للجهــة املختصــة‪ ،‬حضــر‬\n‫أحــد املدعــى عليهــم وهــو الثالــث ولــم يحضــر األول والثانــي‪ ،‬أنكــر‬\n‫املدعــى عليــه احلاضــر الدعــوى‪ ،‬وجــود محضــر استشــمام يتضمــن‬\n‫القبــض علــى املدعــى عليهــم وهــم بحالــة ســكر‪ ،‬صــدر احلكــم بــرد‬\n‫الدعــوى بطلــب إقامــة حــد املســكر وتعزيــر املدعــى عليــه للشــبهة بجلده‬\n‫ثالثــن جلــدة دفعــة واحــدة‪ ،‬تقريــر محاكمــة املدعــى عليهمــا األول‬\n\n                                                                                     ‫‪14‬‬\n\f     ‫والثانــي بعــد حضورهمــا‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n     ‫أنــا‪ .....‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n     ‫مــن هيئــة التحقيــق واالدعــاء العــام واملقيــدة لــدى احملكمــة برقــم‬\n     ‫‪ 3120723‬وتاريــخ ‪1431/11/18‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة اجلزائيــة بالدمــام برقــم ‪ 5036‬وتاريــخ ‪1431/11/18‬ه ـ‬\n     ‫افتتحــت اجللســة يف يــوم الثالثــاء ‪1434/1/20‬ه ـ التاســعة والربــع وفيهــا‬\n     ‫ا فيهــا بصفتــي مدعيـ ًا عامـ ًا بدائــرة‬  ‫قــدم املدعــي العــام ‪ .....‬دعــواه قائـ ً‬\n     ‫االدعــاء العــام لفــرع املنطقــة الشــرقية أدعــي علــى ‪ ..... -1‬ســعودي‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ..... -2 ).....‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم (‪..... -3 ).....‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم (‪ ).....‬حيــث إنــه باالطــاع علــى محضــر تنفيــذ‬\n     ‫املهمــة املعــد مــن قبــل رجــال الضبــط اجلنائــي بالدوريــات األمنيــة وكامل‬\n     ‫أوراق القضيــة تبــن أنــه يف يــوم الســبت ‪1431/10/23‬ه ـ وأثنــاء إقامــة‬\n     ‫نقطــة تفتيــش بحــي الكورنيــش مبدينــة الدمــام مت اســتيقاف ســيارة‬\n     ‫مــن نــوع (‪ )...‬بقيــادة املتهــم‪ .....‬ويرفقــه املتهمــان ‪ .....‬و ‪ .....‬وبإستشــمامهم‬\n     ‫جمعيــا تبــن أنهــم يف حالــة ســكر وبتفتيــش املركبــة عثــر فيهــا علــى‬\n     ‫قــارورة بهــا النصــف مــن الشــراب املســكر فتــم التحفــظ عليهم وبســماع‬\n     ‫أقوالهــم مــن قبــل رجــال الضبــط مبركــز شــرطة جنــوب الدمــام أقــروا‬\n     ‫بصحــة واقعــة القبــض عليهــم وأقــر املتهــم ‪ .....‬بحيــازة وشــرب املســكر‬\n\n‫‪15‬‬\n\f‫يف حــن نفــى املتهمــان ‪.....‬و‪.....‬صحــة مــا ورد مبحضــر االستشــمام‬\n‫وبنــاء علــى مــا ذكــر أقــرر اتهــام كل مــن‪.......... -3 ..... -2 ..... -1 :‬‬\n‫باآلتــي‪ -1 :‬شــرب املســكر ‪ -2‬قيــادة املتهــم الثانــي ‪.....‬الســيارة حتــت‬\n‫تأثيــر املســكر ‪ -3‬حيــازة املتهــم األول ‪.....‬لقــارورة مــاء بهــا والنصــف‬\n‫مــن الشــراب املســكر بقصــد الشــرب وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ -1‬مــا ورد بأقوالهــم األوليــة املنــوه عنهــا املدونــة علــى الصفحــات رقــم‬\n‫(‪ )15-10‬مــن ملــف تقريــر األحــوال األمنيــة املوحــد ‪ -2‬محضــر تنفيــذ‬\n‫املهمــة املنــوه عنــه املرفــق علــى اللفــة رقــم (‪ -3 )2‬محضــر االستشــمام‬\n‫املنــوه عنــه املرفــق علــى اللفــة رقــم (‪ )3‬وبالبحــث عــن ســوابقهم لــم يعثــر‬\n‫لهــم علــى ســوابق وحيــث إن مــا أقــدم عليــه املتهمــون وهــم بكامــل‬\n‫أهليتهــم املعتبــرة شــرعا فعــل محــرم شــرعا ومجــرم نظامــا ممــا يتعــن‬\n‫معــه إحالتهــم إلــى احملكمــة اجلزائيــة وفــق املادتــن (‪ )128-126‬مــن‬\n‫نظــام اإلجــراءات اجلزائيــة للمطالبــة مبــا يلــي‪ :‬أوال إثبــات شــربهم‬\n‫جمعيــا للمســكر واحلكــم عليهــم بحــد الســكر لقــاء ذلــك‪ .‬ثانيــا‪:‬‬\n‫إثبــات حيــازة املتهــم األول ‪ .....‬لقــارورة مــاء بهــا النصــف مــن الشــراب‬\n‫املســكر بقصــد الشــرب واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع‬\n‫غيــره‪ .‬ثالثــا‪ :‬إثبــات قيــادة املتهــم ‪ .....‬للســيارة حتــت تأثيــر املســكر وفــق‬\n‫الفقــرة رقــم (‪ )8‬مــن اجلــدول رقــم (‪ )1‬امللحــق بنظــام املــرور وإفهامــه بــأن‬\n‫عقوبتــه الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )68‬مــن نظــام املــرور‬\n‫تقــرر مــن اجلهــة املختصــة وفــق الفقــرة (‪ )2‬مــن قــرار مجلــس الــوزراء‬\n‫رقــم (‪ )315‬وتاريــخ ‪1428/10/24‬ه ـ هكــذا ادعــى وبعــرض الدعــوى‬\n‫ا مــا ذكــره املدعــي‬     ‫علــى املدعــى عليــه احلاضــر ‪ ..........‬أجــاب قائ ـ ً‬\n‫العــام مــن قيامــي بشــرب املســكر فذلــك غيــر صحيــح ولــم أقــم بشــرب‬\n\n\n                                                                                         ‫‪16‬‬\n\f     ‫املســكر هكــذا أجــاب وأمــا املدعــى عليهمــا ‪.....‬و‪.....‬فلــم يحضــرا ثــم‬\n     ‫جــرى عــرض مــا ذكــره املدعــى عليــه وبســؤال املدعــي العــام البينــة‬\n     ‫علــى دعــواه قــال أطلــب الرجــوع إلــى املعاملــة هكــذا أجــاب ثــم جــرى‬\n     ‫الرجــوع إلــى املعاملــة فوجــدت علــى لفــة رقــم (‪ )3‬محضــر استشــمام‬\n     ‫ـاء علــى مــا‬\n                 ‫املتضمــن القبــض علــى املدعــى عليهــم وهــم بحالــة ســكر فبنـ ً‬\n     ‫تقــدم مــن دعــوى املدعــي العــام وإجابــة املدعــى عليــه وإنــكاره للدعــوى‬\n     ‫ومبــا أن محضــر االستشــمام قرينــة تؤيــد دعــوى املدعــي العــام ومبــا أن‬\n     ‫احلــدود تــدرأ بالشــبهات ونظــر ًا ملــا ذكــره الفقهــاء ومــن ذلــك مــا نــص‬\n     ‫عليــه البهوتــي يف كشــاف القنــاع (‪ )101/14‬بقولــه ( وال يحــد بوجــود‬\n     ‫رائحــة اخلمــر منــه واحلــد يــدرأ بالشــبهة لكــن يعــزر ) لــذا كلــه لــم تثبــت‬\n     ‫لــدي إدانــة املدعــى عليــه ‪.....‬بشــرب املســكر وقــررت اآلتــي‪ :‬أوالً‪ :‬رد‬\n     ‫طلــب املدعــي العــام بإقامــة حــد املســكر علــى املدعــى عليــه ‪.....‬لعــدم‬\n     ‫ثبوتــه‪ .‬ثاني ـاً‪ :‬تعزيــر املدعــى عليــه ‪.....‬باجللــد ثالثــن جلــدة دفعــة واحــدة‬\n     ‫لقــاء شــبهة شــرب املســكر وبــكل مــا تقــدم حكمــت وبعــرض احلكــم‬\n     ‫علــى الطرفــن قــرر املدعــى عليــه القناعــة باحلكــم كمــا قــرر املدعــي‬\n     ‫العــام االعتــراض علــى احلكــم واالكتفــاء بالئحــة الدعــوى العامــة‬\n     ‫وســوف يجــري نظــر الدعــوى بحــق املدعــى عليهمــا ‪.....‬و‪.....‬يف حــال‬\n     ‫حضورهمــا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر‬\n                                                                      ‫يف ‪1434/1/20‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n     ‫لــدى احملكمــة برقــم ‪/34/332748‬ج‪ 2‬وتاريــخ ‪1434/2/10‬ه ـ الواردة‬\n     ‫مــن فضيلــة رئيــس احملكمة اجلزائيــة مبدينة الدمام برقم ‪32/660647‬‬\n\n\n‫‪17‬‬\n\f‫وتاريــخ ‪1434/2/5‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ‪ .....‬املســجل برقــم ‪ 3418751‬وتاريــخ ‪1434/1/20‬ه ـ‬\n‫كل مــن‪ ...../1 :‬و‪ ...../2‬و‪...../3‬‬  ‫اخلــاص بدعــوى املدعــي العــام ضــد ٍ‬\n‫يف قضيــة مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n‫املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                     ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/2/16‬هــ‪.‬‬\n\n\n\n\n                                                                                    ‫‪18‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":14,"source_page_end":18,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"26eb54ef1f82a93c102270e85573ee567e01b4b71b5bc8acfc111e3583340483","normalized_text_hash":"a166a7a41217b08398f5c7ec20977239fcf9accf6ded6153774c9b6fabfc9213","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p14-3418751"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"6d0fe669-b29b-5635-b852-d0b2b153bd34","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتسبب يف إصابة- مطالبة املدعي باملجازاة -إيجابية التقريرين الطبين للمدعى - إقرار املدعى عليه بالدعوى -إدانة املدعى عليه.","document_number":"34348135","case_number":"34325504","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/3","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتسبب يف إصابة- مطالبة املدعي باملجازاة -إيجابية التقريرين الطبين للمدعى - إقرار املدعى عليه بالدعوى -إدانة املدعى عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/11/3 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34348135 :‬‬\n                   ‫َر ْق ُم الدعوى‪34325504 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34390495‬تاريخه‪1434/12/29:‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالضــرب وتســبب يف إصابــة‪-‬‬\n‫مطالبــة املدعــي باملجــازاة ‪ -‬إيجابيــة التقريريــن الطبيــن للمدعــى ‪-‬‬\n                ‫إقــرار املدعــى عليــه بالدعــوى ‪ -‬إدانــة املدعــى عليــه‪.‬‬\n\n\n\n\n                                                          ‫املرء مؤاخذ بإقراره‪.‬‬\n\n\n\n\n‫ادعــى وكيــل املدعــي بــأن املدعــى عليــه احلاضــر معــه قــام باالعتــداء‬\n‫علــى موكلــه بالضــرب ممــا تســبب يف إصابتــه بكدمــات يف الوجــه‬\n‫وكســر لبعــض األســنان‪ ،‬ولــذا فقــد طلــب احلكــم عليه بعقوبــة تعزيرية‬\n‫لقــاء ذلــك ‪ -‬أقــر املدعــى عليــه مبــا جــاء يف الدعــوى جملــة وتفصيــا‪-‬‬\n‫املدعــى عليــه تســبب يف إصابــة املدعــي بكدمــات مــع تــورم علــى العــن‬\n‫اليســرى وكدمــات يف الوجــه وكســر ثالثــة أســنان أماميــة فوقيــة‬\n‫ومــدة الشــفاء املتوقعــة تصــل إلــى أســبوعني حســب التقريريــن الطبيــن‬\n‫‪ -‬قضــت احملكمــة بإدانــة املدعــى عليــه مبــا نســب إليــه وقــررت ســجنه‬\n‫ملــدة عشــرين يومـ ًا وجلــده أربعــن جلــدة دفعــة واحــدة‪ -‬قنــع املدعــى عليــه‬\n\n\n                                                                                      ‫‪368‬‬\n\f      ‫باحلكــم وعــارض عليــه وكيــل املدعــي‪ -‬قــررت محكمــة االســتئناف‬\n                                                  ‫املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪1434/11/3‬ه ـ لدي أنا‬\n      ‫ـاء علــى املعاملــة احملالــة‬\n                                 ‫‪ ......‬القاضــي باحملكمــة اجلزائيــة بالدمــام وبنـ ً‬\n      ‫إلينــا مــن رئيــس احملكمــة برقــم (‪ )34325504‬وتاريــخ ‪1434/4/3‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر ‪ ....‬ســعودي مبوجــب الهويــة الوطنيــة رقــم‬\n      ‫(‪ )...‬الوكيــل الشــرعي عــن مبوجــب الوكالــة الصــادرة من كتابة عدل‬\n      ‫الباحــة برقــم (‪ )33426118‬و تاريــخ ‪1433/10/15‬ه ـ والتــي تخولــه‬\n      ‫املرافعــة واملدافعــة و الصلــح والتنــازل و قبــول احلكــم واالعتــراض عليــه‬\n      ‫و ادعــى علــى احلاضــر معــه ‪ ....‬ســعودي مبوجــب بطاقــة الهويــة الوطنيــة‬\n      ‫ا يف دعــواه لقــد تعــرض موكلــي لالعتــداء بالضــرب‬          ‫رقــم (‪ ).....‬قائ ـ ً‬\n      ‫مــن قبــل املدعــى عليــه و قــد نتــج عــن ذلــك إصابــات يف موكلــي عبــارة‬\n      ‫عــن كدمــات مــع تــورم علــى العــن اليســرى و كدمــات علــى الوجــه و‬\n      ‫كســر ثالثــة أســنان أماميــة فوقيــة أطلــب احلكــم بتعزيــره لقــاء ذلــك‬\n      ‫هــذه دعــواي وأحصرهــا يف ذلــك و أســأله اإلجابــة و بســؤال املدعــى‬\n      ‫عليــه أجــاب بقولــه مــا ذكــره املدعــي وكالــة يف دعــواه صحيــح فقــد‬\n      ‫قمــت باالعتــداء بضــرب موكلــه و أنــا نــادم علــى مــا بــدر منــي هــذه‬\n      ‫إجابتــي و بعــد تدويــن مــا ســبق جــرى االطــاع علــى التقريــر الطبــي‬\n      ‫الصــادر مــن مجمــع الدمــام الطبــي برقــم (‪16/18096‬ت‪ )41/‬و تاريــخ‬\n      ‫‪1432/10/22‬ه ـ و التقريــر الطبــي اإلحلاقــي لــه و املــدون علــى اللفــة‬\n      ‫السادســة عشــرة فوجــدت اإلصابــات التــي حلقــت مــوكل املدعــي‬\n\n‫‪369‬‬\n\f‫مطابقــة ملــا ورد يف الدعــوى و مــدة الشــفاء يف الكدمــات التــي علــى‬\n‫العــن و الوجــه وكســر األســنان خمســة أيــام و مــدة شــفاء الســن القاطــع‬\n‫األمامــي العلــوي والســن القاطــع األمامــي اجلانبــي األميــن و الســن القاطــع‬\n‫الســفلي اجلانبــي األميــن مــن يــوم إلــى أســبوعني فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة املتضمنــة املصادقــة و حيــث إن املــرء مؤاخــذ بإقــراره‬\n‫وبنــاء علــى التقريريــن الطبيــن املشــار لهمــا أعــاه و حيــث إن مــا قــام‬\n‫بــه املدعــى عليــه فعــل محــرم وفيــه اعتــداء علــى اآلخريــن وســامتهم‬\n‫وموجــب ذلــك التعزيــر و حيــث حصــر املدعــي وكالــة دعــواه يف ذلــك‬\n‫لــذا فقــد حكمــت بســجن املدعــى عليــه عشــرين يوم ـ ًا وجلــده أربعــن‬\n‫جلــدة دفعــة واحــدة و بعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n‫قناعتــه بــه وقــرر املدعــي وكالــة عــدم القناعــة وطلــب رفــع احلكــم‬\n‫إلــى محكمــة االســتئناف بالئحــة فأجيــب لطلبــه ومت تســليمه نســخة‬\n‫مــن احلكــم وأفهــم بتقــدمي اعتراضــه خــال مهلــة ثالثــن يوم ـ ًا وأنــه إذا‬\n‫انتهــت هــذه املهلــة ولــم يتقــدم باعتراضــه ســقط حقــه يف ذلــك وســوف‬\n‫يتــم رفــع احلكــم إلــى محكمــة االســتئناف بــدون الئحــة وبــاهلل التوفيــق‬\n           ‫وصلــى اهلل علــى نبينــا محمــد و بــه حــرر يف ‪1434/11/3‬ه ـ ‪.‬‬\n‫ويف يــوم االثنــن املوافــق ‪1435/1/29‬ه ـ افتتحــت اجللســة الســاعة‬\n‫الثانيــة عشــرة وقــد عــادت املعاملــة مــن محكمــة االســتئناف برقــم‬\n‫(‪ )34/2730007‬وتاريــخ ‪1435/1/23‬ه ـ املتعلقــة بدعــوى ‪ ...‬ضــد ‪...‬‬\n‫وبرفقهــا القــرار الصــادر مــن الدائرة اجلزائية الثانية برقم (‪)34390495‬‬\n‫وتاريــخ ‪1434/12/29‬ه ـ املتضمــن املصادقــة علــى احلكــم لــذا جــرى‬\n‫إحلــاق ذلــك حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                  ‫وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n\n\n                                                                                        ‫‪370‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":368,"source_page_end":370,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d0cb43de98d15a21dedd6927a8b5d6a42e794fb7d44c2b4e2be590fdf57ad52f","normalized_text_hash":"9e2adfe58af42b722a5a6617728cf410065d436c0e74f0bfb05685c2affc923f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p368-34348135"},{"id":"181937f4-0708-5733-9647-e71cf074bf15","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالسب والشتم والتعيير -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعي غير موصلة -مين املدعى عليه على نفي الدعوى -إقرار املدعى عليه بالتعيير -إدانة املدعى عليه بالتعيير.","document_number":"34290521","case_number":"34357162","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/7","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالسب والشتم والتعيير -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعي غير موصلة -مين املدعى عليه على نفي الدعوى -إقرار املدعى عليه بالتعيير -إدانة املدعى عليه بالتعيير.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/8/7 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34290521 :‬‬\n                         ‫َر ْق ُم الدعوى‪34357162 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34311739‬تاريخه‪1434/9/3:‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالســب والشــتم والتعيير ‪ -‬مطالبة‬\n      ‫املدعــي باملجــازاة ‪ -‬إنــكار املدعــى عليــه الدعــوى ‪ -‬بينــة املدعــي غيــر‬\n      ‫موصلــة ‪ -‬ميــن املدعــى عليــه علــى نفــي الدعــوى ‪ -‬إقــرار املدعــى عليــه‬\n                                       ‫بالتعييــر ‪ -‬إدانــة املدعــى عليــه بالتعييــر‪.‬‬\n\n\n\n\n                                      ‫‪ -1‬قوله تعالى‪ (( :‬وال تنابزوا باأللقاب))‪.‬‬\n      ‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬كل املســلم علــى املســلم حــرام‬\n                                               ‫دمــه ومالــه وعرضــه) رواه مســلم‪.‬‬\n                                                                ‫‪ -3‬العادة محكمة‪.‬‬\n\n\n\n      ‫ادعــت املدعيــة بــأن املدعــى عليــه قــام بســبها وشــتمها وتعييرهــا بــأن‬\n      ‫زواجهــا غيــر شــرعي‪ ،‬وطلبــت احلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلك‪-‬‬\n      ‫أنكــر املدعــى عليــه مــا جــاء يف دعــوى املدعيــة ســوى أنــه وصــف زواجها‬\n      ‫بأنــه زواج مســيار‪ -‬طلبــت احملكمــة مــن املدعيــة أن تقــدم بينتهــا علــى‬\n      ‫دعواهــا فأحضــرت شــاهدين إال أن شــهادتهما غيــر موصلــة إلثبــات‬\n      ‫دعواهــا‪ -‬طلبــت املدعيــة ميــن املدعــى عليــه علــى نفــي دعواهــا فأداهــا‬\n      ‫طبــق مــا طلــب منــه‪ -‬املدعــى عليــه أقــر بأنــه وصــف زواج املدعيــة بأنــه‬\n\n‫‪371‬‬\n\f‫مســيار علــى ملــئ مــن النــاس وهــذا يعــد عرفـ ًا مــن قبيــل التعييــر كمــا‬\n‫أن شــهادة الشــهود قرينــة قويــة علــى كثــرة تعرضــه للمدعيــة باإلســاءة‬\n‫واإليــذاء اللفظــي‪ -‬قضــت احملكمــة بعــدم ثبــوت دعــوى املدعيــة بتلفــظ‬\n‫املدعــى عليــه مبــا جــاء يف دعواهــا كمــا قضــت بإدانــة املدعــى عليــه‬\n‫بتعييــر املدعيــة وإيذائهــا وقــررت ســجنه ملــدة خمســة عشــر يوم ـاً‪-‬‬\n‫قنعــت املدعيــة باحلكــم وعــارض عليــه املدعــى عليــه‪ -‬قــررت محكمــة‬\n                                           ‫االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن ‪1434/8/1‬ه ـ ويف متــام الســاعة‬\n‫التاســعة والنصــف افتتحــت اجللســة لــدي أنــا ‪ .....‬املــازم القضائــي‬\n‫باحملكمــة اجلزائيــة بابهــا واملكلــف بنظــر هــذه القضيــة مــن قبــل‬\n‫ـاء علــى املعاملــة‬\n                  ‫فضيلــة رئيــس احملكمــة اجلزائيــة بابهــا املســاعد وبنـ ً‬\n‫احملالــة لنــا مــن فضيلــة برقــم ‪ 34357162‬بتاريــخ ‪1434/8/1‬هـ واملقيدة‬\n‫باحملكمــة برقــم ‪ 341855532‬بتاريــخ ‪1434/8/1‬ه ـ وفيهــا حضــرت‬\n‫‪ ........‬ســعودية اجلنســية بالســجل املدنــي رقــم ‪ ......‬ويرافقهــا والدهــا‬\n‫واملعــرف بهــا ‪ ....‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪ ......‬وحضــر‬\n‫حلضورهــا ‪ ....‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪ .....‬وادعــت األولــى‬\n‫قائلــة ان هــذا احلاضــر معــي قــام بشــتمي وســبي وتعييــري أمــام النــاس‬\n‫واألقــارب يف املناســبات واالجتماعــات وقــال ان زواجــي مــن زوجــي‬\n‫غيــر شــرعي اطلــب إثبــات ذلــك ومعاقبتــه عليــه شــرعا هــذه دعــواي‬\n‫وبعرضــه علــى املدعــى عليــه أجــاب بــان مــا ذكرتــه املدعيــة يف دعواهــا‬\n‫غيــر صحيــح وكل مــا ذكرتــه ان زواجهــا دخلــي وهــو أشــبه باملســيار‬\n\n                                                                                    ‫‪372‬‬\n\f      ‫وبســؤاله هــل كان ذلــك يف مجمــع مــن النــاس فأجــاب بأنــه اســتفزه‬\n      ‫احــد اقاربهــا فذكــر مــا ذكــر امــام النــاس وبعرضــه علــى املدعيــة‬\n      ‫اجابــت بــان الصحيــح مــا ذكرتــه يف دعــواي وبســؤال املدعيــة هــل لديهــا‬\n      ‫بينــه علــى مــا ذكــرت اجابــت بــان لديهــا شــهود يشــهدون بأنــه قــال ان‬\n      ‫زواجــي مــن زوجــي غيــر شــرعي واطلــب امهالــي إلحضارهــم فأجبتهــا‬\n      ‫لطلبهــا ورفعــت اجللســة لذلــك حتــى يــوم األحــد ‪1434/8/7‬ه ـ الســاعة‬\n      ‫التاســعة وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬احلمــد اهلل وحــدة وبعــد‬\n      ‫ويف يــوم األحــد ‪1434/8/7‬ه ـ ويف متــام الســاعة احلاديــة عشــرة فتحــت‬\n      ‫اجللســة بحضــور الطرفــان واملعــرف باملدعــى عليهــا وبســؤال املدعيــة عــن‬\n      ‫بينتهــا التــي اســتمهلت مــن أجلهــا احضــرت للشــهادة وادائهــا ســعودي‬\n      ‫اجلنســية بالســجل املدنــي رقــم ســعودي اجلنســية بالســجل املدنــي رقــم‬\n      ‫وشــهد األول قائــا اننــا كنــا يف املستشــفى ودخــل علينــا املدعــى عليــه‬\n      ‫وقــال خلنــي اشــوف هــذا الــذي حذائــي اكــرم مــن وجهــة اللــي زوج بنتــه‬\n      ‫مســيار اشــهد بــاهلل العظيــم علــى ذلــك وشــهد الثانــي قائــا بأننــا كنــا‬\n      ‫يف جلســة عشــاء عنــد احــد اعمامــي وكان املدعــى عليــه موجــود يف‬\n      ‫اجللســة فقــال لــي ان عمــك حطهــا مجــراره ســكن زوجهــا عنــده حتــت‬\n      ‫فقلــت لــه ترضــاه ألختــك او بنــت اختــك فقــال ال أعمــل جــرار واشــهد اهلل‬\n      ‫العظيــم علــى ذلــك وبعــرض الشــهود وشــهادتهم علــى املدعــى عليــه اجاب‬\n      ‫قائــا بانــي اعــرف الشــهود عــم املدعيــة و ابــن عمهــا وال اقبــل شــهادتهم‬\n      ‫وأمــا الشــهادة فإننــي بالفعــل قلــت بــان الــزواج مســيار النهــم منعونــي‬\n      ‫مــن الدخــول علــى اختــي التــي هــي أمهــا وأنــا لــم اقــل إال انــه مســيار‬\n      ‫وبســؤال املدعــى عليهــا هــل لديهــا مزيــد بينــة علــى دعواهــا اجابــت بانــه‬\n      ‫ليــس عندهــا اال مــا ذكــر فأفهمــت املدعيــة بــان بينتهــا غيــر موصلــة‬\n\n\n‫‪373‬‬\n\f‫وانــه ليــس لهــا اال ميــن املدعــى عليــه علــى نفــي دعواهــا فقــررت رغبتهــا‬\n‫فيهــا لذلــك جــرى توجيــه اليمــن علــى املدعــى عليــه بعــد تخويفــه مــن‬\n‫خطرهــا فاســتعد لبذلهــا وحلــف قائــا واهلل العظيــم اننــي لــم اتلفــظ‬\n‫علــى املدعيــة بقولــي ان زواجهــا غيــر شــرعي وال أي لفــظ يســئ لشــرفها‬\n‫واهلل العظيــم هكــذا حلــف فبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــة‬\n‫وملــا قــرره الطرفــان ونظــرا إلنــكار املدعــى عليــه انــه قــال للمدعيــة بــان‬\n‫زواجهــا غيــر شــرعي ولقصــور بينتهــا وعــدم اتفــاق الشــهود علــى لفــظ‬\n‫الدعــوى ولبذلــه اليمــن علــى ذلــك بعــد ان طلبتهــا املدعيــة وإلقــراره‬\n‫بنبزهــا بــان زواجهــا مســيار امــام جمــع مــن النــاس وهــذا ممــا يعــاب عنــد‬\n‫اهــل املنطقــة والن العــادة محكمــة كمــا قــرر الفقهــاء وملــا شــهد بــه‬\n‫الشــهود مــن شــهادة تعــد قرينــه قويــة علــى إســاءته لهــا وكثــر وايذائهــا‬\n‫بلســانه ولقولــه صلــى اهلل عليــه وســلم (كل املســلم علــى املســلم حــرام‬\n‫دمــه ومالــه وعرضــه) رواه مســلم ولقولــه تعالــى ( وال تنابــزوا باأللقــاب)‬\n‫لذلــك كلــه فلــم يثبــت لــدي تلفــظ املدعــى عليــه علــى املدعيــة بقولــه‬\n‫بــان زواجهــا غيــر شــرعي وثبــت لــدي انــه أذاهــا وعيرهــا بــان زواجهــا‬\n‫مســيار وحكمــت بتعزيــر املدعــى عليــه بســجنه خمســة عشــر يومـ ًا لقــاء‬\n‫ذلــك وبهــذا حكمــت وبعــرض احلكــم علــى الطرفــن قــررت املدعيــة‬\n‫القناعــة بــه وقــرر املدعــى عليــه اعتراضــه عليــه مــن غيــر الئحــة وســوف‬\n‫يتــم رفــع كامــل املعاملــة إلــى محكمــة االســتئناف لتدقيــق احلكــم‬\n‫كاملتبــع‪ .‬جــرى النطــق باحلكــم بتاريــخ ‪1434/8/7‬ه ـ ورفعــت اجللســة‬\n‫بعــد ذلــك عنــد الســاعة احلاديــة عشــرة والنصــف وصلــى اهلل وســلم علــى‬\n                                                                   ‫نبينــا محمــد ‪.‬‬\n‫ويف يــوم األربعــاء ‪1434/10/ 7‬ه ـ افتتحــت اجللســة يف متــام الســاعة‬\n\n\n                                                                                       ‫‪374‬‬\n\f      ‫الواحدة ظهر ًا وفيها عادت املعاملة رفق خطاب فضيلة رئيس محكمة‬\n      ‫االســتئناف مبنطقــة عســير رقــم ‪ 342046767‬يف ‪1434/9/16‬ه ـ‬\n      ‫مرفقــا بهــا قــرار التصديــق الصــادر مــن الدائــرة اجلزائيــة الثانيــة رقــم‬\n      ‫‪ 34311739‬يف ‪1434/9/3‬ه ـ املتضمــن نــص احلاجــة منــه مــا يلــي‬\n      ‫(وبدراســة القــرار وصــورة ضبطــه وأراق املعاملــة تقــررت املوافقــة علــى‬\n      ‫احلكــم واهلل املوفــق ) انتهــى بتوقيــع وختــم قاضــي اســتئناف الشــيخ‪/‬‬\n      ‫(‪ ).....‬وبتوقيــع وختــم قاضــي اســتئناف الشــيخ‪ ).....(/‬وبتوقيــع وختــم‬\n      ‫رئيــس الدائــرة الشــيخ‪ ).....(/‬ولــذا جــرى مبوجبــه التهميــش ورفعــت‬\n      ‫اجللســة عنــد الســاعة الواحــدة والربــع وصلــى اهلل وســلم علــى نبينــا‬\n                                                                               ‫محمــد‪.‬‬\n\n\n\n\n‫‪375‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":371,"source_page_end":375,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d550c0fa6130456cce6b9eb58be40d46a3ce2e29e245fd912cecf4f4def6e112","normalized_text_hash":"a7c8258e583b7b2cb7c76ef361f518af02793e234547a72d431f39f949e612b9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p371-34290521"},{"id":"2264ceb8-5a79-5967-bdbf-a6fd923c506e","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتهديد بالقتل -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -عجز املدعي عن إقامة البينة -مين املدعى عليه على نفي الدعوى -رد الدعوى.","document_number":"34349902","case_number":"34429222","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/4","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتهديد بالقتل -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -عجز املدعي عن إقامة البينة -مين املدعى عليه على نفي الدعوى -رد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/11/4 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34349902 :‬‬\n                   ‫َر ْق ُم الدعوى‪34429222 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34363059‬تاريخه‪1434/11/19 :‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالضــرب وتهديــد بالقتل ‪ -‬مطالبة‬\n‫املدعــي باملجــازاة ‪ -‬إنــكار املدعــى عليــه الدعــوى ‪ -‬عجــز املدعــي عــن‬\n ‫إقامــة البينــة‪ -‬ميــن املدعــى عليــه علــى نفــي الدعــوى ‪ -‬رد الدعــوى‪.‬‬\n\n\n\n\n‫قــول النبــي صلــى اهلل عليــه وســلم ‪( :‬البينــة علــى املدعــي واليمــن علــى‬\n                                                                 ‫املدعــى عليه)‪.‬‬\n\n\n\n‫ادعــى املدعــي علــى املدعــى عليهمــا بــأن األول قــام بالتعــاون مــع الثانــي‬\n‫بضربــه علــى وجهــه وتهديــده بالقتــل‪ ،‬ولــذا فقــد طلــب احلكــم عليهمــا‬\n‫بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أنكــر املدعــى عليهمــا مــا جــاء يف الدعــوى‬\n‫جملــة وتفصيــا‪ -‬املدعــي ال بينــة لــه علــى إثبــات دعــواه وطلــب ميــن‬\n‫املدعــى عليهمــا علــى نفيهــا فأدياهــا طبــق مــا طلــب منهمــا‪ -‬قضــت‬\n‫احملكمــة بصــرف النظــر عــن دعــوى املدعــي وأخلــت ســبيل املدعــى‬\n‫عليهمــا منهــا ‪ -‬قنــع املدعــى عليهمــا باحلكــم وعــارض عليــه املدعــي ‪-‬‬\n                    ‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n                                                                                     ‫‪376‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بحائــل برقــم ‪ 34429222‬وتاريــخ ‪ 1434/09/17‬ه ـ املقيــدة‬                ‫ّ‬\n      ‫باحملكمــة برقــم ‪ 342205090‬وتاريــخ ‪ 1434/09/17‬ه ـ ففــي يــوم‬\n      ‫الثالثــاء املوافــق‪ 1434/11/04‬ه ـ افتتحــت اجللســة الســاعة احلاديــة‬\n      ‫عشــرة وفيهــا حضــر (‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم (‪ ).....‬وادعــى كل مــن (‪ ).....‬ســعودي مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪ ).....‬و(‪ ).....‬ســعودي مبوجــب الســجل املدنــي رقــم(‪ ).....‬قائــا يف حترير‬\n      ‫دعــواه إنــي كنــت يف مزرعــة والــدي أعمــل علــى احلراثــة فدخلــت علــي‬\n      ‫ســيارة يقودهــا املدعــى عليــه األول (‪ ).....‬وبصحبتــه ابنــه املدعــى عليــه‬\n      ‫الثانــي (‪ ).....‬فقــال لــي املدعــى عليــه األول وش عنــدك بهذا فقلت أحرث‬\n      ‫فقــال مــن أنــت ابــن لــه فقلــت ولــد فقــال تعــال انــزل ثــم نــزل ومــد يــده إلــي‬\n      ‫فأنزلنــي بالقــوة فحاولــت أدافــع عــن نفســي فقــام املدعــى عليــه الثانــي‬\n      ‫(‪ ).....‬مبســكي مــع رقبتــي وضربنــي املدعــى عليــه األول علــى وجهــي‬\n      ‫وقــال واهلل ألقتلــك أنــت وأبــوك وش جابكــم ملزرعتنــا وابنــه وضــع‬\n      ‫إصبعــه عنــد عينــي وقــال ألرميــك بالســاح أنــت وأبــوك ثــم قــال واهلل‬\n      ‫إن مــا ذبحــت ابــوك مانــي رجــل ثــم قــال شــل حراثتــك وال أشــوفك هنــا‬\n      ‫ثــم انصــرف ملــا شــاهد أخوتــي هكــذا ادعــى املدعــي أطلــب مجازاتهــم‬\n      ‫وتأديبهــم وبســؤال املدعــى عليــه األول أجــاب قائــا مــا ذكــره املدعــي‬\n      ‫يف دعــواه ضــدي غيــر صحيــح فلــم أدخــل املزرعــة ولــم أهــدده هكــذا‬\n      ‫أجــاب وبســؤال املدعــى عليــه الثانــي أجــاب قائــا مــا ذكــره املدعــي‬\n\n‫‪377‬‬\n\f‫يف دعــواه ضــدي غيــر صحيــح فلــم أدخــل املزرعــة ولــم أهــدده هكــذا‬\n‫أجــاب وبســؤال املدعــي عــن البينــة قــال ليــس عنــدي بينــة وأطلــب ميــن‬\n‫املدعــى عليهمــا علــى نفــي دعــواي وبعــرض ذلــك علــى املدعــى عليهمــا‬\n‫قــاال ال مانــع عندنــا علــى أداء اليمــن علــى نفــي دعــواه ضدنــا فجــرى‬\n‫بيــان اليمــن التــي يحلفهــا املدعــى عليهمــا فوافقــا علــى ذلــك فأذنــت‬\n‫للمدعــى عليــه األول بــأداء اليمــن فحلــف قائــا واهلل إن مــا ذكــره‬\n‫املدعــي يف دعــواه ضــدي كلــه غيــر صحيــح هكــذا حلــف ثــم أذنــت‬\n‫للمدعــى عليــه الثانــي بــأداء اليمــن فحلــف قائــا واهلل إن مــا ذكــره‬\n‫املدعــي يف دعــواه ضــدي كلــه غيــر صحيــح هكــذا حلــف فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليهمــا أنكــرا مــا‬\n‫جــاء يف الدعــوى واملدعــي ليــس لديــه بينــة وطلــب ميــن املدعــى عليهمــا‬\n‫وأدى املدعــى عليهمــا اليمــن كمــا طلــب منهمــا ولقــول النبــي صلــى اهلل‬\n‫عليــه وســلم البينــة علــى املدعــي واليمــن علــى مــن أنكــر فقــد صرفــت‬\n‫النظــر عــن طلــب املدعــي مجــازاة املدعــى عليهمــا وأخليــت ســبيلهما هــذا‬\n‫مــا ظهــر لــي وبــه حكمــت واهلل أعلــم وأحكــم وبعــرض احلكــم علــى‬\n‫الطرفــن قــرر املدعــي قــرر عــدم القناعــة بهــذا احلكــم وطلــب رفعــه‬\n‫حملكمــة االســتئناف بــدون الئحــة اعتراضيــة وبعــرض احلكــم علــى‬\n‫املدعــى عليهمــا قــررا القناعــة بهــذا احلكــم وبهــذا انتهــت هــذه اجللســة‬\n‫يف متــام الســاعة احلاديــة عشــرة والنصــف وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/11/4‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة املختصــة‬\n‫بتدقيــق القضايــا اجلزائيــة األولــى مبحكمــة االســتئناف مبنطقــة حائــل‬\n‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بحائــل‬\n\n\n                                                                                   ‫‪378‬‬\n\f      ‫برقــم ‪ 342205090‬وتاريــخ ‪1434/11/11‬ه ـ واملقيــدة لدينــا برقــم‬\n      ‫‪ 342205090‬وتاريــخ ‪1434/11/12‬ه ـ واملرفــق بهــا الصــك الشــرعي‬\n      ‫الصــادر مــن فضيلــة الشــيخ‪ ).....(/‬القاضــي باحملكمــة اجلزائيــة بحائــل‬\n      ‫برقــم ‪ 34349902‬يف ‪1434/11/4‬ه بدعــوى (‪ ).....‬ضــد كل مــن‪/1 :‬‬\n      ‫(‪ ).....‬ســعودي اجلنســية ‪ ).....( /2‬ســعودي اجلنســية‪ .‬بشــأن دعــوى خاصــة‬\n      ‫(اعتــداء) وقــد تضمــن الصــك حكــم صاحــب الفضيلــة وفقــه اهلل علــى‬\n      ‫املدعــى عليهمــا علــى النحــو املفصــل يف الصــك املرفــق وبدراســة الصــك‬\n      ‫وصــورة ضبطــه وأوراق املعاملــة‪ :‬جــرت املصادقــة علــى مــا حكــم بــه‬\n      ‫فضيلتــه بالصــك املشــار إليــه‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                                  ‫وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪379‬‬\n\f                       ‫كشاف املوضوعات‬\n\n‫الصفحة‬                    ‫املوضوع‬                      ‫التصنيف‬     ‫م‬\n\n\n          ‫دعوى عامة ضد وافد عربي بالتشبه بالنساء‬\n  ‫‪5‬‬                                                     ‫شذوذ‬       ‫‪1‬‬\n                    ‫ووضع مساحيق نسائية‬\n\n\n         ‫دعوى عامة ضد مواطن بالتشبه بالنساء ونزع‬\n  ‫‪9‬‬      ‫شعر صدره ويديه واالستعداد ملمارسة الرذيلة‬      ‫شذوذ‬       ‫‪2‬‬\n           ‫واالعتداء على رجال هيئة األمر باملعروف‬\n\n\n           ‫دعوى عامة ضد مواطن بوضعه مساحيق‬\n  ‫‪17‬‬       ‫نسائية والتشبه بالنساء والعثور على صور‬       ‫شذوذ‬       ‫‪3‬‬\n                     ‫خليعة يف جواله‬\n\n\n         ‫دعوى عامة ضد وافدة عربية باخلروج من منزل‬\n  ‫‪27‬‬                                                   ‫تغيب فتاة‬   ‫‪4‬‬\n                       ‫زوجها دون إذنه‬\n\n\n          ‫دعوى عامة ضد امرأتني باالشتراك بإفساد‬\n            ‫وتخبيب زوجة غير سعودية على زوجها‬\n  ‫‪32‬‬                                                   ‫تغيب فتاة‬   ‫‪5‬‬\n           ‫وحتريضها على الهرب بأبنائها السعوديني‬\n            ‫القصر وعدم جتاوبهما أثناء االستجواب‬\n\n\n         ‫دعوى عامة ضد امرأة بالتغيب عن منزل ذويها‪،‬‬\n  ‫‪66‬‬                                                   ‫تغيب فتاة‬   ‫‪6‬‬\n                ‫والسفر دون محرم لغرض سيء‬\n\n\n           ‫دعوى عامة ضد شخص بإقامة عالقة غير‬\n  ‫‪71‬‬      ‫شرعية بفتاة وتغييبها عن منزل ذويها وإيوائه‬   ‫تغيب فتاة‬   ‫‪7‬‬\n                        ‫لها واالختالء بها‬\n\f‫الصفحة‬                   ‫املوضوع‬                    ‫التصنيف‬   ‫م‬\n\n\n         ‫دعوى عامة ضد وافد بالتحرش بالفتيات عن‬\n  ‫‪79‬‬     ‫طريق إمساك عضوه الذكري وإخراجه أمام‬         ‫حترش‬     ‫‪8‬‬\n                       ‫مدرسة البنات‬\n\n\n         ‫دعوى عامة ضد شخص مبحاولة إدخال حدث‬\n  ‫‪86‬‬                                                 ‫حترش‬     ‫‪9‬‬\n               ‫إلى منزله بالقوة لغرض سيء‬\n\n\n         ‫دعوى عامة ضد وافدين بالتحرش بفتاتني عند‬\n  ‫‪92‬‬      ‫دخولهما احملل ‪ ،‬حيث يقف الثاني للمراقبة‬    ‫حترش‬     ‫‪10‬‬\n                   ‫ليساعد األول يف التحرش‬\n\n\n           ‫دعوى عامة ضد شخص بالتحرش اجلنسي‬\n  ‫‪99‬‬      ‫بامرأة ؛ حيث طلب ملس يدها وكشف غطاء‬        ‫حترش‬     ‫‪11‬‬\n                     ‫وجهها فهربت‬\n\n\n           ‫دعوى عامة ضد شخص مبعاكسة امرأة‬\n ‫‪103‬‬                                                 ‫حترش‬     ‫‪12‬‬\n                    ‫وإزعاجها بالرسائل‬\n\n\n            ‫دعوى عامة ضد شخص بالتحرش بفتاة‬\n ‫‪108‬‬        ‫باإلمساك بها من كتفها وتقبيلها وملس‬      ‫حترش‬     ‫‪13‬‬\n                  ‫مؤخرتها بيده لغرض سيء‬\n\n\n         ‫دعوى عامة ضد شخصني مبعاكستهما للنساء‬\n ‫‪112‬‬      ‫يف األسواق حيث يوجد لدى كل واحد منهما‬      ‫حترش‬     ‫‪14‬‬\n             ‫قصاصة ورقية كتب عليها رقم هاتفه‬\n\n\n          ‫دعوى عامة ضد شخص بالتحرش بالطالبات‬\n ‫‪116‬‬                                                 ‫حترش‬     ‫‪15‬‬\n            ‫جنسيا ؛ مستغال عمله حارسا للمدرسة‬\n\f‫الصفحة‬                    ‫املوضوع‬                       ‫التصنيف‬    ‫م‬\n\n\n         ‫دعوى عامة ضد شخص بإقامة عالقة محرمة‬\n           ‫مع فتاة ال متت له بصلة شرعية ‪ ،‬واخللوة بها‬\n ‫‪122‬‬                                                     ‫حترش‬      ‫‪16‬‬\n          ‫وإزعاجها برسائل بذيئة وفاضحة وغير الئقة‬\n                           ‫والتغرير بها‬\n\n\n         ‫دعوى عامة ضد شخص بإقامة عالقة محرمة‬\n ‫‪130‬‬       ‫مع امرأة اشتكت من اعتداءاته ‪ ،‬وحيازة‬          ‫حترش‬      ‫‪17‬‬\n                ‫مقاطع جنسية وتصوير ذكره‬\n\n\n          ‫دعوى عامة ضد شخص مبعاكسته النساء‬\n ‫‪138‬‬                                                     ‫حترش‬      ‫‪18‬‬\n         ‫وحيازته جلوال يحوي عددا من املقاطع اجلنسية‬\n\n\n         ‫دعوى خاصة من شخص ضد امرأة اشتكته‬\n          ‫بأنه ال يصلي ال يف البيت وال يف املسجد ‪،‬‬\n ‫‪147‬‬                                                    ‫قذف زوجة‬   ‫‪19‬‬\n           ‫وميارس أعماال مشينة معها ومع غيرها ‪،‬‬\n                    ‫ويتعاطى املخدرات‬\n\n\n          ‫دعوى عامة ضد شخص بالتطاول على أئمة‬\n ‫‪153‬‬      ‫املساجد ووصفهم بالكالب التي تنبح وهم‬          ‫سب وشتم‬    ‫‪20‬‬\n                 ‫يقرؤون القران وقت الصالة‬\n\n\n           ‫دعوى عامة ضد شخصني ‪ ،‬فاألول بالسب‬\n                ‫ٍ‬\n          ‫مستوصف أثناء‬    ‫والشتم إلحدى العامالت يف‬\n ‫‪159‬‬                                                    ‫سب وشتم‬    ‫‪21‬‬\n           ‫تأديتها عملها وتهديدها ‪ ،‬والثاني بالتلفظ‬\n             ‫بألفاظ غير الئقة على إحدى العامالت‬\n\n\n         ‫دعوى عامة ضد شخص بالتلفظ بألفاظ بذيئة‬\n ‫‪167‬‬     ‫على الرسول صلى اهلل عليه وسلم ‪ ،‬ومالحقته‬       ‫سب وشتم‬    ‫‪22‬‬\n         ‫للمجني عليه وصدمه بسيارته وتهديده بالقتل‬\n\f‫الصفحة‬                    ‫املوضوع‬                     ‫التصنيف‬       ‫م‬\n\n\n          ‫بسبه لرجل وقذفه‬\n                      ‫دعوى عامة ضد شخص ّ‬\n ‫‪170‬‬                                                  ‫سب وشتم‬       ‫‪23‬‬\n          ‫أثناء تأديته مهام عمله يف صيدلية مستشفى‬\n\n\n           ‫دعوى خاصة من شخص ضد رجل لتقدميه‬\n ‫‪177‬‬     ‫شكوى كيدية ضده فأحيل للتحقيق ولم يثبت‬        ‫إيذاء الغير‬   ‫‪24‬‬\n                    ‫حينها ّبينة على كالمه‬\n\n\n           ‫دعوى خاصة من وكيل مدعية ضد امرأة‬\n ‫‪181‬‬                                                  ‫إيذاء الغير‬   ‫‪25‬‬\n            ‫قامت بصفع موكلته بيدها على وجهها‬\n\n\n             ‫مدع ضد رجل‬‫دعوى خاصة من وكيل ٍ‬\n         ‫باالعتداء على موكله بضربه بآلة حادة (مفتاح‬\n ‫‪183‬‬                                                  ‫إيذاء الغير‬   ‫‪26‬‬\n          ‫معدني) على رأسه مما جنم عنه جرح قطعي‬\n                        ‫سطحي يف رأسه‬\n\n\n          ‫دعوى خاصة من شخص ضد رئيس حترير‬\n         ‫إحدى الصحف لنشره حكما قضائيا يخصه‬\n ‫‪188‬‬                                                  ‫إيذاء الغير‬   ‫‪27‬‬\n           ‫مما تسبب بضرر مادي حلق به من تشهير‬\n                     ‫وإضرار بسمعته‬\n\n\n         ‫دعوى خاصة ضد مدعى عليهم قاموا باستغالل‬\n          ‫السلطة املمنوحة لهم يف جهة عملهم بكتابة‬\n ‫‪196‬‬                                                  ‫إيذاء الغير‬   ‫‪28‬‬\n           ‫خطاب إلى الوزير يتضمن معلومات مخالفة‬\n                       ‫ملجريات التحقيق‬\n\n\n            ‫مدع ضد شخص‬ ‫دعوى خاصة من وكيل ٍ‬\n ‫‪201‬‬     ‫بتلفظه على موكله يف قضية حضانة بينه وبني‬     ‫إيذاء الغير‬   ‫‪29‬‬\n                           ‫زوجته‬\n\f‫الصفحة‬                    ‫املوضوع‬                     ‫التصنيف‬       ‫م‬\n\n\n          ‫دعوى خاصة ضد وافد عربي لتطاوله على‬\n ‫‪209‬‬      ‫املدعي بالكالم ومالحقته واضطراره إلى‬        ‫إيذاء الغير‬   ‫‪30‬‬\n         ‫ضيق لسيارته حتى أجبروه على الوقوف‬\n                                       ‫ٍ‬   ‫طريق‬\n\n\n         ‫دعوى خاصة ضد شخص تلفظ بألفاظ بذيئة‬\n ‫‪213‬‬      ‫ثم تشابك مع املدعي باأليدي‪ ،‬وضربه بيده‬      ‫إيذاء الغير‬   ‫‪31‬‬\n             ‫وبالعقال مما تسبب يف إصابته بجروح‬\n\n\n         ‫دعوى خاصة ضد شخص قدم بالغا يف مركز‬\n ‫‪222‬‬      ‫الشرطة بأنه أشهر السالح يف وجهه فأُوقِ َف‬   ‫إيذاء الغير‬   ‫‪32‬‬\n                    ‫على إثر ذلك ملدة يوم واحد‬\n\n\n           ‫سبه وتلفظ عليه‬\n                       ‫دعوى خاصة ضد شخص َّ‬\n ‫‪227‬‬                                                  ‫إيذاء الغير‬   ‫‪33‬‬\n                  ‫بألفاظ بذيئة ال يذكرها‬\n\n\n          ‫دعوى خاصة ضد شخص ضربه على وجهه‬\n ‫‪232‬‬                                                  ‫إيذاء الغير‬   ‫‪34‬‬\n                         ‫بيده‬\n\n\n          ‫دعوى خاصة ضد شخص ضربه على ركبته‬\n ‫‪238‬‬                                                  ‫إيذاء الغير‬   ‫‪35‬‬\n          ‫وأحدث بها التواء شديدا أثرت على احلركة‬\n\n\n          ‫دعوى خاصة بوالية عن ابن ضد ُم َعلِّم ضرب‬\n ‫‪243‬‬     ‫االبن على رأسه بيده ‪ ،‬كما حاول ضرب األب‬      ‫إيذاء الغير‬   ‫‪36‬‬\n               ‫أيضا متلفظا عليه مهددا بالقتل‬\n\n\n           ‫دعوى خاصة ضد امرأة بسبها واتهامها له‬\n ‫‪249‬‬                                                  ‫إيذاء الغير‬   ‫‪37‬‬\n                        ‫بالنفاق والكذب‬\n\f‫الصفحة‬                   ‫املوضوع‬                    ‫التصنيف‬       ‫م‬\n\n\n         ‫دعوى خاصة ضد شخص حرق سيارة املدعي‬\n ‫‪253‬‬                                                ‫إيذاء الغير‬   ‫‪38‬‬\n           ‫دون أي دليل مما تسبب بتشويه سمعته‬\n\n\n           ‫مدع ضد ابن اخته بضربه بيده‬‫دعوى من ٍ‬\n         ‫مما تسبب يف إصابته بكدمة يف الشفة العليا‬\n ‫‪261‬‬                                                ‫إيذاء الغير‬   ‫‪39‬‬\n         ‫وسحجة يف الركبة اليسرى ‪ ،‬مع تهديده عن‬\n                      ‫طريق رسائل اجلوال‬\n\n\n          ‫دعوى خاصة ضد شخص طرد املدعي من‬\n ‫‪268‬‬                                                ‫إيذاء الغير‬   ‫‪40‬‬\n              ‫العمل لديه إثر خالفات بينهما‬\n\n\n           ‫دعوى خاصة ضد شخص ضرب املدعي‬\n ‫‪273‬‬                                                ‫إيذاء الغير‬   ‫‪41‬‬\n           ‫بالعقال ولعن والديه بعد مشادة بينهما‬\n\n\n          ‫شوه سمعته وذلك‬\n                      ‫دعوى خاصة ضد شخص ّ‬\n ‫‪278‬‬      ‫باحلديث عنه بني املدرسني على أنه صاحب‬     ‫إيذاء الغير‬   ‫‪42‬‬\n                ‫فكر ضال وال والء له للوطن‬\n\n\n         ‫مدع ضد شخص رفع‬  ‫دعوى خاصة من وكيل ٍ‬\n ‫‪288‬‬     ‫شكوى كيدية ضد موكله اتهمه أنه هدده‬         ‫إيذاء الغير‬   ‫‪43‬‬\n                    ‫فحول للتحقيق‬\n                             ‫بالقتل ِّ‬\n\n\n         ‫دعوى خاصة ضد شخص اعتدى عليه بالتلفظ‬\n ‫‪302‬‬                                                ‫إيذاء الغير‬   ‫‪44‬‬\n                  ‫عليه وتصويره خلالف بينهما‬\n\n\n          ‫دعوى خاصة ضد شخص دخل بيته وغرفة‬\n ‫‪308‬‬                                                ‫إيذاء الغير‬   ‫‪45‬‬\n                     ‫زوجته لغرض سيء‬\n\f‫الصفحة‬                    ‫املوضوع‬                      ‫التصنيف‬       ‫م‬\n\n\n         ‫دعوى خاصة ضد شخص اعتدى عليه بالضرب‬\n ‫‪312‬‬     ‫مما تسبب يف إصابته بكدمات يف الشفة العليا‬     ‫إيذاء الغير‬   ‫‪46‬‬\n           ‫وحتت الذقن وحول الرقبة والكتف األيسر‬\n\n\n         ‫دعوى خاصة ضد شخص أرسل له رسالة جوال‬\n ‫‪316‬‬                                                   ‫إيذاء الغير‬   ‫‪47‬‬\n                        ‫تتضمن شتمه‬\n\n\n         ‫دعوى خاصة ضد شخص اعتدى عليه بالضرب‬\n           ‫مما تسبب يف إصابته بكدمات بالوجه‬\n ‫‪319‬‬                                                   ‫إيذاء الغير‬   ‫‪48‬‬\n         ‫والركبتني وسجحات بالظهر وحتركت بعض‬\n                ‫أسنانه مع نزيف يسير بالفم‬\n\n\n          ‫سبه ولعن والديه ‪،‬‬\n                         ‫دعوى خاصة ضد شخص ّ‬\n ‫‪323‬‬                                                   ‫إيذاء الغير‬   ‫‪49‬‬\n                    ‫وضايقه وطارده بالسيارة‬\n\n\n            ‫دعوى من مدعية ضد شخص تلفظ عليها‬\n ‫‪326‬‬          ‫واتهمها يف شرفها حيث ذكر أن أحد‬          ‫إيذاء الغير‬   ‫‪50‬‬\n          ‫األشخاص يكثر الدخول واخلروج إلى شقتها‬\n\n\n         ‫سبه وتلفظ عليه أثناء‬\n                           ‫دعوى خاصة ضد شخص ّ‬\n ‫‪330‬‬                                                   ‫إيذاء الغير‬   ‫‪51‬‬\n                  ‫ترافعهما أمام إحدى احملاكم‬\n\n\n           ‫دعوى من وكيل مدعية ضد شخص قذف‬\n ‫‪336‬‬                                                   ‫إيذاء الغير‬   ‫‪52‬‬\n             ‫موكلته ووصفها بالكالم البذيء‬\n\n\n           ‫دعوى خاصة ضد امرأة قدمت ضده بالغا‬\n ‫‪343‬‬      ‫لهيئة األمر باملعروف والنهي عن املنكر بغير‬   ‫إيذاء الغير‬   ‫‪53‬‬\n             ‫حق فقبض عليه وأوقف ملدة يوم واحد‬\n\f‫الصفحة‬                    ‫املوضوع‬                     ‫التصنيف‬       ‫م‬\n\n\n         ‫دعوى خاصة ضد شخص تلفظ عليه بقول ‪ :‬يا‬\n ‫‪347‬‬                                                  ‫إيذاء الغير‬   ‫‪54‬‬\n                ‫فاجر ‪ .‬ودعا عليه باملوت والزوال‬\n\n\n         ‫مدع ضد شخص سبه وشتمه أمام‬‫دعوى من ٍ‬\n ‫‪351‬‬                                                  ‫إيذاء الغير‬   ‫‪55‬‬\n                  ‫سكنه ‪ ،‬وحاول ضربه‬\n\n\n           ‫مدع ضد شخص سبه واتهمه‬  ‫دعوى من ٍ‬\n ‫‪355‬‬        ‫بالسكر أمام جمع من الناس يف دائرة‬         ‫إيذاء الغير‬   ‫‪56‬‬\n                          ‫حكومية‬\n\n\n            ‫مدع ضد شخص قذفه بالسب‬    ‫دعوى من ٍ‬\n ‫‪359‬‬        ‫والشتم قائال ‪ :‬أنتم أهل اللحى مجرمني‬      ‫إيذاء الغير‬   ‫‪57‬‬\n         ‫ونصابني ودجالني ومنافقني ثم هدده باالغتيال‬\n\n\n         ‫مدع ضد شخص قذفه وسبه وشتمه‬   ‫دعوى من ٍ‬\n ‫‪363‬‬                                                  ‫إيذاء الغير‬   ‫‪58‬‬\n             ‫يف الدائرة احلكومية التي يعمالن بها‬\n\n\n           ‫مدع ضد شخص اعتدى‬ ‫دعوى من وكيل ٍ‬\n ‫‪368‬‬      ‫على موكله بالضرب مما تسبب يف إصابته‬         ‫إيذاء الغير‬   ‫‪59‬‬\n          ‫بكدمات يف الوجه وكسر لبعض األسنان‬\n\n\n          ‫دعوى من مدعية ضد شخص سبها وشتمها‬\n ‫‪371‬‬                                                  ‫إيذاء الغير‬   ‫‪60‬‬\n               ‫وعيرها بأن زواجها غير شرعي‬\n\n\n         ‫مدع ضد شخصني ‪ :‬أحدهما ضربه‬    ‫دعوى من ٍ‬\n ‫‪376‬‬       ‫واآلخ ِر ساعده‬\n                    ‫َ‬     ‫‪،‬‬ ‫بالقتل‬ ‫وهدده‬ ‫على وجهه‬     ‫إيذاء الغير‬   ‫‪61‬‬\n                          ‫وتعاون معه‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":376,"source_page_end":387,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"31119c4814738e625752bccf0545f7414a32c06d120a66db7e99f4196a86e87e","normalized_text_hash":"26c7a7835fe00eb724d752b93d8cfc9e78da6ebdc2c8c0c0d27287eae0e63c83","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p376-34349902"},{"id":"6cfb8d16-a041-527d-bc60-3b8af31cd35d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب مسكر -حيازة بقصد االستعمال -االجتماع على مفسدة -التعزير للتهمة .","document_number":"34351747","case_number":"3097","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية على املعاملة املقيدة لدى المحكمة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/05","year":"1434","subject":"مسكر -شرب مسكر -حيازة بقصد االستعمال -االجتماع على مفسدة -التعزير للتهمة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫رقم الصك‪ 34351747 :‬تاريخه‪1434/11/05 :‬هـ‬\n                            ‫رقم الدعوى‪3097 :‬‬\n                  ‫رقم قرار التصديق من محكمة‬\n     ‫االستئناف‪ 34381427:‬تاريخه‪1434/12/18:‬هـ‬\n\n\n     ‫مســكر ‪ -‬شــرب مســكر ‪ -‬حيــازة بقصــد االســتعمال ‪ -‬االجتمــاع علــى‬\n                                                 ‫مفســدة ‪ -‬التعزيــر للتهمــة ‪.‬‬\n\n\n\n\n     ‫لعــن رســول اهلل صلــى اهلل عليــه وســلم يف اخلمــر ثمانيــة ( شــاربها‬\n     ‫وســاقيها وحاملهــا واحملمولــة إليــه وعاصرهــا ومعتصرهــا وبائعهــا‬\n                                                            ‫وآكل ثمنهــا ) ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وحيازتــه لــه‬\n     ‫بقصــد االســتعمال ‪،‬واالجتمــاع علــى مفســدة وطلــب إثبــات مــا أســند‬\n     ‫إليــه ‪،‬واحلكــم عليــه بحــد املســكر وعقوبــة لقــاء حيــازة املســكر‬\n     ‫واالجتمــاع علــى مفســدة ‪،‬حيــث مت القبــض عليــه مــن قبــل أعضــاء هيئــة‬\n     ‫األمــر باملعــروف والنهــي عــن املنكــر بشــقة وبرفقــة حــدث يلبــس مالبس‬\n     ‫ضيقــة ‪،‬واتضــح أنــه بحالــة غيــر طبيعيــة وباستشــمامه تبــن انبعــاث‬\n     ‫رائحــة املســكر مــن أنفاســه ‪،‬وأثبــت التقريــر الكيميائــي الشــرعي‬\n     ‫إيجابيــة العينــة ملــادة الكحــول اإليثيلــي ‪،‬وصــادق املدعــى عليــه علــى‬\n     ‫دعــوى املدعــي العــام ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بجلــده‬\n     ‫ثمانــن جلــده حــد املســكر دفعــة واحــدة وســجنه ســبعة أيــام ‪،‬ولتوجــه‬\n\n‫‪5‬‬\n\f‫التهمــة للمدعــى عليــه باالجتمــاع علــى مفســدة تعزيــره بالســجن ثالثــة‬\n‫أشــهر وجلــده ســبعني جلــدة مفرقــة علــى دفعتــن ‪،‬وقنــع املدعــى عليــه‬\n‫‪،‬وصــدق احلكــم مــن محكمــة‬  ‫‪،‬واعتــرض املدعــي العــام بــدون الئحــة ُ‬\n                                                               ‫االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n‫‪ .....‬القاضــي باحملكمــة اجلزائيــة باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة يف محافظــة اخلبــر برقــم ‪3097‬‬\n‫وتاريــخ ‪ 1430/08/19‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3010275‬وتاريــخ‬\n‫‪ 1430/08/19‬ه ـ ففــي يــوم األربعــاء املوافق‪ 1434/11/05‬هـ افتتحت‬\n‫اجللســة الســاعة ‪ 09 : 00‬وفيهــا قــدم املدعــي العــام ‪.....‬الئحــة دعــوى‬\n‫ا فيهــا انــه‬ ‫عامــة ضــد م ‪ .....‬ســعودي بالســجل املدنــي رقــم (‪ ).....‬قائ ـ ً‬\n‫بتاريــخ ‪1429/1/28‬ه ـ مت القبــض علــى املدعــى عليــه املذكــور باخلبــر‬\n‫اجلنوبيــة داخــل شــقة مــن قبــل رجــال هيئــة األمــر باملعــروف والنهــي عــن‬\n‫املنكــر رفــق آخــر (فــرزت لــه أوراق مســتقلة) واتضــح أنــه بحالــة غيــر‬\n‫طبيعيــة اشــتباه (ســكر) وباستشــمامه تبــن انبعــاث رائحــة املســكر‬\n‫مــن أنفاســه وقــد اثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪).....‬‬\n‫ايجابيــة مــا ضبــط مــع املدعــى عليــه ملــادة الكحــول االيثيلــي وبنســبة‬\n‫مســكرة وباســتجوابه اعتــرف بشــرب املســكر وانــه احضــره مــن‬\n‫شــخص بحرينــي ال يعرفــه وقــد أســفر التحقيــق معــه عــن توجيــه االتهــام‬\n‫للمدعــى عليــه بشــرب املســكر وحيازتــه بقصــد االســتعمال الشــخصي‬\n‫واالجتمــاع علــى مفســدة وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه‬\n\n                                                                                         ‫‪6‬‬\n\f    ‫علــى ســوابق مســجلة وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل‬\n    ‫أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب‬\n    ‫إثبــات مــا أســند إليــه واحلكــم عليــه بحــد املســكر لقــاء شــربه لــه كمــا‬\n    ‫أطلــب احلكــم عليــه بعقوبــة تزجــره وتــردع غيــره لقــاء حيازتــه للمســكر‬\n    ‫واجتماعــه مــع آخــر علــى مفســدة هــذه دعــواي وبســؤال املدعــى عليــه‬\n    ‫عــن الدعــوى أجــاب بقولــه الصحيــح أنــه مت القبــض علــي يف تاريــخ‬\n    ‫‪1429/1/28‬ه ـ عنــد منتصــف الليــل وأنــا متواجــد داخــل شــقه مفروشــة‬\n    ‫يف حــي ‪.....‬يف اخلبــر وكنــت أنــا يف حالــة ســكر حيــث إنــي شــربت‬\n    ‫املســكر وقــد كان معــي كأس زجاجــي يحتــوي علــى املســكر وهــو‬\n    ‫يعــود لــي وكنــت أنــوي شــربه وكان معــي يف نفــس الشــقة ‪.....‬ويبلــغ مــن‬\n    ‫العمــر يف ذلــك الوقــت حوالــي ســبعة عشــر عامـ ًا فأنــا أكبــر منــه بنحــو‬\n    ‫تســع أعــوام وهــو مــن قــام بدعوتــي إلــى الشــقة فهــو لديــه شــذوذ وكان‬\n    ‫وقــت القبــض علينــا يلبــس مالبــس ضيقــة وقــد وضــع الكحــل يف عينيــه‬\n    ‫ولــم يشــرب هــو املســكر وكنــا لوحدنــا يف الشــقة ولــم يحصــل بيننــا‬\n    ‫أي شــيء وتعرفــت عليــه كونــه جــار لنــا يف نفــس احلــارة وأنــا نــادم علــى‬\n    ‫فعلــي وتائــب إلــى اهلل تعالــى هكــذا أجــاب بعــد ذلــك جــرى الــر جــوع‬\n    ‫إلــى اللفــة رقــم (‪ )15‬وتضمنــت التقريــر الكيمــاوي الشــرعي وهــو‬\n    ‫كمــا ذكــر املدعــي العــام يف دعــواه كمــا جــرى الرجــوع إلــى اللفــة‬\n    ‫رقــم (‪ )20‬وتضمنــت محضــر القبــض ويظهــر منــه أن املضبــوط كأس‬\n    ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬ ‫زجاجــي بــه الربــع مــن اخلمــر فبنـ ً‬\n    ‫وحيــث أقــر املدعــى عليــه بشــرب املســكر وحيازتــه بقصــد الشــرب‬\n    ‫وهــذا مــن كبائــر الذنــوب فقــد لعــن رســول اهلل صلــى اهلل عليــه وســلم‬\n    ‫يف اخلمــر ثمانيــة (شــاربها وســاقيها وحاملهــا واحملمولــة إليــه وعاصرهــا‬\n\n\n‫‪7‬‬\n\f‫ومعتصرهــا وبائعهــا واكل ثمنهــا) واللعــن ال يكــون إال علــى كبيــرة‬\n‫مــن كبائــر الذنــوب وحيــث أقــر املدعــى عليــه بأنــه قبــض عليــه ومعــه‬\n‫حــدث قــد وضــع الكحــل يف عينيــه ويلبــس مالبــس ضيقــه وهــذا يوجــه‬\n‫التهمــة للمدعــى عليــه باالجتمــاع علــى املفســدة لــذا فقــد قــررت مــا يلــي‬\n‫أو ًال ثبــت لــدي شــرب املدعــى عليــه للمســكر وقــررت أن يجلــد لقــاء‬\n‫ذلــك حــد املســكر ثمانــن جلــده دفعــة واحــدة ثاني ـ ًا ثبــت لــدي حيــازة‬\n‫املدعــى عليــه كأس زجاجــي يحتــوي علــى املســكر بقصــد الشــرب‬\n‫وقــررت تعزيــر املدعــى عليــه لقــاء ذلــك بســجنه مــدة ســبعة أيــام ثالث ـ ًا‬\n‫توجــه التهمــه للمدعــى عليــه باالجتمــاع علــى مفســدة وقــررت تعزيــره‬\n‫لقــاء ذلــك بســجنه مــدة ثالثــة أشــهر وجلــده ســبعني جلــده علــى دفعتــن‬\n‫متســاويتني بينهمــا مــدة ال تقــل عــن عشــرة أيــام وبــن جلــد احلــد وجلــد‬\n‫التعزيــر مــدة ال تقــل عــن عشــرة أيــام وبذلــك يكــون ســجن املدعــى‬\n‫عليــه هــو ثالثــة أشــهر وســبعة أيــام اعتبــار ًا مــن تاريــخ إيقافــه ومبــا تقــدم‬\n‫حكمــت وبعــرض احلكــم قنــع املدعــى عليــه ولــم يقنــع املدعــي العــام‬\n‫مكتفيـ ًا مبــا قــدم يف الئحــة الدعــوى وأقفلــت اجللســة الســاعة العاشــرة‬\n                                             ‫وصلــى اهلل وســلم علــى نبينــا محمــد‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/2589973‬ج‪ 2‬وتاريــخ ‪1434/11/12‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم‬\n‫‪ 30/10275‬وتاريــخ ‪1434/11/9‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪..... /‬املســجل برقــم ‪34351747‬‬\n‫وتاريــخ ‪1434/11/5‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪...../‬ي يف‬\n\n\n                                                                                            ‫‪8‬‬\n\f    ‫قضيــة مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n    ‫ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n    ‫املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                    ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/12/18‬ه ـ ‪.‬‬\n\n\n\n\n‫‪9‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":5,"source_page_end":9,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7b024e4a02df3358ed894c649fa3f8553df0c203c010e0e69a54a826b467f0e0","normalized_text_hash":"296fb5d3ebd7092ee1fffce6cad23993a62629c6f01edc770686c2f566f51267","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p5-34351747"},{"id":"dd18f0b7-4779-517a-82f1-e6c654745460","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب مسكر -احلدود تدرأ بالشبهات -رد الدعوى -عدم ثبوت االدعاء -التعزير باجللد للشبهة .","document_number":"34166404","case_number":"3797","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/18","year":"1434","subject":"مسكر -شرب مسكر -احلدود تدرأ بالشبهات -رد الدعوى -عدم ثبوت االدعاء -التعزير باجللد للشبهة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34166404 :‬تاريخه‪1434/3/18 :‬هـ‬\n                        ‫رقم الدعوى ‪3797:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34214644‬تاريخه‪1434/05/18:‬هـ‬\n\n\n ‫مســكر ‪ -‬شــرب مســكر ‪ -‬احلــدود تــدرأ بالشــبهات ‪ -‬رد الدعــوى‪ -‬عــدم‬\n                         ‫ثبــوت االدعــاء ‪ -‬التعزيــر باجللــد للشــبهة ‪.‬‬\n\n\n\n\n ‫مــا نــص عليــه البهوتــي يف كشــاف القنــاع ‪ ( 101/14‬وال يحــد بوجــود‬\n                 ‫رائحــة اخلمــر منــه واحلــد يــدرأ بالشــبهة لكــن يعــزر ) ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وطلــب إثبــات‬\n ‫مــا أســند إليــه واحلكــم عليــه بحــد شــرب املســكر ‪،‬حيــث لوحــظ‬\n ‫املدعــى عليــه بحالــة غيــر طبيعيــة فتبــن أنــه بحالــة ســكر وباستشــمامه‬\n ‫تبــن انبعــاث رائحــة املســكر مــن أنفاســه وأنكــر املدعــى عليــه شــرب‬\n ‫املســكر ودفــع بخروجــه مــن املستشــفى وشــربه للــدواء قبــل القبــض‬\n ‫عليــه وجــرى الكتابــة للمستشــفى فصــادق علــى دفــع املدعــى عليــه وأنــه‬\n ‫راجعهــم ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بــرد دعــوى املدعــي‬\n ‫العــام باملطالبــة بإقامــة حــد املســكر لعــدم ثبوتــه وتعزيــر املدعــى عليــه‬\n ‫للشــبهة بشــرب املســكر بجلــده ثالثــن جلــدة دفعــة واحــدة واعتــرض‬\n ‫‪،‬وصــدق‬\n       ‫املدعــى عليــه بالئحــة اعتراضيــة واملدعــي العــام بــدون الئحــة ُ‬\n                                          ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n                                                                                      ‫‪10‬‬\n\f     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n     ‫‪ .....‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة مــن‬\n     ‫هيئــة التحقيــق واالدعــاء العــام واملقيــدة لــدى احملكمة برقــم ‪3116113‬‬\n     ‫وتاريــخ ‪1431/8/14‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫اجلزائيــة بالدمــام برقــم ‪ 3797‬وتاريــخ ‪1431/8/14‬ه ـ افتتحــت اجللســة‬\n     ‫يف يــوم الثالثــاء ‪1433/6/17‬ه ـ الســاعة التاســعة والنصــف وفيهــا قــدم‬\n     ‫ا فيهــا بصفتــي مدعيـ ًا عام ًا بدائــرة االدعاء‬\n                                                     ‫املدعــي العــام ‪.....‬دعــواه قائـ ً‬\n     ‫العــام لفــرع املنطقــة الشــرقية أدعــي علــى‪..... /‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم (‪ ).....‬حيــث إنــه باالطــاع علــى محضــر تنفيــذ‬\n     ‫املهمــة املعــد مــن قبــل رجــال الضبــط اجلنائــي بالدوريــات األمنيــة بالدمــام‬\n     ‫تبــن أنــه يف يــوم األربعــاء ‪1431/7/27‬ه ـ لوحــظ املدعــى عليــه يف حالــة‬\n     ‫غيــر طبيعيــة وبالتأكــد منــه تبــن أنــه بحالــة ســكر وباستشــمامه‬\n     ‫تبــن انبعــاث رائحــة املســكر مــن أنفاســه وباســتجواب املدعــى عليــه‬\n     ‫أنكــر شــرب املســكر وأنكــر أن تكــون رائحــة املســكر قــد انبعثــت‬\n     ‫مــن أنفاســه وأفــاد بأنــه كان قــد خــرج لتــوه مــن أحــد العمليــات وأن‬\n     ‫هــذا الســبب يف عــدم متاســكه وأضــاف أن الرائحــة املنبعثــة منــه هــي‬\n     ‫رائحــة الــدواء الــذي يســتخدمه وانتهــى التحقيــق إلــى اتهــام املدعــى‬\n     ‫عليــه بشــرب املســكر وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬محضــر‬\n     ‫تنفيــذ املهمــة املرفــق علــى اللفــة رقــم (‪ -2 )2‬محضــر االستشــمام املنــوه‬\n     ‫عنــه واملــدون علــى الصفحــة رقــم (‪ )4‬مــن ملــف التحقيــق املرفــق لفــة‬\n     ‫رقــم (‪ )1‬وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســوابق وحيــث إن‬\n     ‫مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل‬\n‫‪11‬‬\n\f‫محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات إدانتــه مبــا نســب إليــه‬\n‫واحلكــم عليــه بحــد شــرب املســكر هكــذا ادعــى وبعــرض الدعــوى‬\n‫ا مــا ذكــره املدعــي العــام مــن قيامــي‬  ‫علــى املدعــى عليــه أجــاب قائ ـ ً‬\n‫بشــرب املســكر فذلــك غيــر صحيــح والصحيــح أننــي كنــت خرجــت‬\n‫مــن املستشــفى يف ذلــك اليــوم بعدمــا قمــت بعمليــة لــدى املستشــفى‬\n‫(‪)........‬ولــم أقــم بــاألكل وكنــت أعــرج يف املشــي وشــاهدني رجــال‬\n‫األمــن فظنــوا أننــي بحالــة ســكر وقبضــوا علــي هكــذا أجــاب وبعــرض‬\n‫ذلــك علــى املدعــي العــام قــال مــا ذكــره املدعــى عليــه غيــر صحيــح‬\n‫والصحيــح مــا ذكرتــه يف دعــواي هكــذا أجــاب وبســؤال املدعــى‬\n‫عليــه البينــة علــى مــا ذكــره قــال أطلــب الكتابــة للمستشــفى (‪).........‬‬\n‫للتأكــد مــن ذلــك هكــذا أجــاب ويف جلســة أخــرى حضــر املدعــي العــام‬\n‫ولــم يحضــر املدعــى عليــه وقــد كنــا كتبنــا خطــاب للمستشــفى فوردنــا‬\n‫اخلطــاب مــن مديــر مجمــع الدمــام الطبــي برقــم ‪.....‬يف ‪1433/7/27‬ه ـ‬\n‫ونصــه مــا يلــي ( بعــد البحــث يف احلاســب اآللــي لدينــا تبــن أن املدعــى‬\n‫عليــه راجــع قســم اإلســعاف فقــط منــذ ســنتني ) ثــم جــرى ســؤال املدعــي‬\n‫العــام البينــة علــى دعــواه فقــال أطلــب الرجــوع إلــى املعاملــة هكــذا‬\n‫أجــاب ويف يــوم األربعــاء ‪1434/3/18‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n‫الطرفــان ثــم جــرى الرجــوع إلــى املعاملــة فوجــدت علــى لفــة رقــم (‪ )1‬ص‬\n‫(‪ )6‬محضــر استشــمام املتضمــن طبــق مــا ذكــر املدعــي العــام يف دعــواه‬\n‫ـاء علــى مــا تقــدم مــن دعــوى املدعــي العــام وإجابــة املدعــى عليــه‬ ‫فبنـ ً‬\n‫ـاء محضــر االستشــمام ومبــا أن املدعــى عليــه قــد‬   ‫وإنــكاره للدعــوى وبنـ ً‬\n‫راجــع املستشــفى قبــل القبــض عليــه وهــذه شــبهة ومبــا أن احلــدود تــدرأ‬\n‫بالشــبهات ونظــر ًا ملــا ذكــره الفقهــاء ومــن ذلــك مــا نــص عليــه البهوتــي‬\n\n\n                                                                                     ‫‪12‬‬\n\f     ‫يف كشــاف القنــاع (‪ ).....‬بقولــه ( وال يحــد بوجــود رائحــة اخلمــر منــه‬\n     ‫واحلــد يــدرأ بالشــبهة لكــن يعــزر ) لــذا كلــه لــم تثبــت لــدي إدانــة املدعى‬\n     ‫عليــه وقــررت اآلتــي‪ :‬أوالً‪ :‬رد دعــوى املدعــي العــام باملطالبــة بإقامــة حــد‬\n     ‫املســكر علــى املدعــى عليــه لعــدم ثبوتهــا‪ .‬ثاني ـاً‪ :‬تعزيــر املدعــى عليــه‬\n     ‫باجللــد ثالثــن جلــدة دفعــة واحــدة لقــاء شــبهة شــرب املســكر وبــكل‬\n     ‫مــا تقــدم حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n     ‫عــدم القناعــة باحلكــم وطلــب االســتئناف بالئحــة يقدمهــا فأفهمتــه بأنه‬\n     ‫ســوف يجــري تســليمه بعــد قليــل نســخة مــن احلكــم ليقــدم اعتراضــه‬\n     ‫خــال ثالثــن يوم ـ ًا يكــون حقــه يف االســتئناف بعدهــا ســاقطا ففهــم‬\n     ‫ذلــك وأمــا املدعــي العــام فقــرر االعتــراض علــى احلكــم واالكتفــاء‬\n     ‫بالئحــة الدعــوى العامــة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                                                     ‫محمــد‪ .‬حــرر يف ‪1434/3/18‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n     ‫لــدى احملكمــة برقــم ‪/34/1086643‬ج‪ 2‬وتاريــخ ‪1434/5/4‬ه ـ الواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم ‪31/16113‬‬\n     ‫وتاريــخ ‪1434/4/29‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n     ‫القاضــي باحملكمــة الشيخ‪...../‬املســجل برقــم ‪ 34166404‬وتاريــخ‬\n     ‫‪1434/3/18‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ ...../‬يف قضيــة‬\n     ‫مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n     ‫فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n     ‫علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                    ‫وســلم‪ .‬حــرر يف ‪1434/5/18‬ه ـ ‪.‬‬\n\n\n‫‪13‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":10,"source_page_end":13,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"62a644ecbc85c49a01acb308f69130f164e293ef02c7102fce6ae9879874be0e","normalized_text_hash":"a42b539a04e381cabab4844206e32f9c7944c97a8d7eb56c79d800876e5ad2c8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p10-34166404"},{"id":"4b75080d-1a3c-5558-9331-a743f08dcee1","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب مسكر -حيازة بقصد الشرب -قيادة السيارة حتت تأثير املسكر -ال يحد حد املسكر بالرائحة -التعزير باجللد","document_number":"3418751","case_number":"5036","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/20","year":"1434","subject":"مسكر -شرب مسكر -حيازة بقصد الشرب -قيادة السيارة حتت تأثير املسكر -ال يحد حد املسكر بالرائحة -التعزير باجللد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3418751 :‬تاريخه‪1434/1/20:‬هـ‬\n                      ‫رقم الدعوى‪5036 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 3438319‬تاريخه‪1434/02/16 :‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب مســكر ‪ -‬حيــازة بقصــد الشــرب ‪ -‬قيــادة الســيارة حتــت‬\n‫تأثيــر املســكر ‪ -‬ال يحــد حــد املســكر بالرائحــة ‪ -‬التعزيــر باجللــد‬\n                                                              ‫للشــبهة ‪.‬‬\n\n\n\n\n‫مــا نــص عليــه البهوتــي يف كشــاف القنــاع ‪ ( 101/14‬وال يحــد بوجــود‬\n                ‫رائحــة اخلمــر منــه واحلــد يــدرأ بالشــبهة لكــن يعــزر ) ‪.‬‬\n\n\n\n\n‫دعــوى املدعــي العــام ضــد املدعــى عليهــم ثالثــة بقيامهــم بشــرب‬\n‫املســكر وقيــادة الثانــي الســيارة وهــو حتــت تأثيــر املســكر وحيــازة‬\n‫األول للمســكر بقصــد الشــرب وطلــب إثبــات مــا أســند إليهــم واحلكــم‬\n‫عليهــم بحــد املســكر وتعزيــر األول للحيــازة وإثبــات إدانــة الثانــي بقيــادة‬\n‫الســيارة حتــت تأثيــر املســكر وعقابــه عائــد للجهــة املختصــة‪ ،‬حضــر‬\n‫أحــد املدعــى عليهــم وهــو الثالــث ولــم يحضــر األول والثانــي‪ ،‬أنكــر‬\n‫املدعــى عليــه احلاضــر الدعــوى‪ ،‬وجــود محضــر استشــمام يتضمــن‬\n‫القبــض علــى املدعــى عليهــم وهــم بحالــة ســكر‪ ،‬صــدر احلكــم بــرد‬\n‫الدعــوى بطلــب إقامــة حــد املســكر وتعزيــر املدعــى عليــه للشــبهة بجلده‬\n‫ثالثــن جلــدة دفعــة واحــدة‪ ،‬تقريــر محاكمــة املدعــى عليهمــا األول‬\n\n                                                                                     ‫‪14‬‬\n\f     ‫والثانــي بعــد حضورهمــا‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n     ‫أنــا‪ .....‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n     ‫مــن هيئــة التحقيــق واالدعــاء العــام واملقيــدة لــدى احملكمــة برقــم‬\n     ‫‪ 3120723‬وتاريــخ ‪1431/11/18‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة اجلزائيــة بالدمــام برقــم ‪ 5036‬وتاريــخ ‪1431/11/18‬ه ـ‬\n     ‫افتتحــت اجللســة يف يــوم الثالثــاء ‪1434/1/20‬ه ـ التاســعة والربــع وفيهــا‬\n     ‫ا فيهــا بصفتــي مدعيـ ًا عامـ ًا بدائــرة‬  ‫قــدم املدعــي العــام ‪ .....‬دعــواه قائـ ً‬\n     ‫االدعــاء العــام لفــرع املنطقــة الشــرقية أدعــي علــى ‪ ..... -1‬ســعودي‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ..... -2 ).....‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم (‪..... -3 ).....‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم (‪ ).....‬حيــث إنــه باالطــاع علــى محضــر تنفيــذ‬\n     ‫املهمــة املعــد مــن قبــل رجــال الضبــط اجلنائــي بالدوريــات األمنيــة وكامل‬\n     ‫أوراق القضيــة تبــن أنــه يف يــوم الســبت ‪1431/10/23‬ه ـ وأثنــاء إقامــة‬\n     ‫نقطــة تفتيــش بحــي الكورنيــش مبدينــة الدمــام مت اســتيقاف ســيارة‬\n     ‫مــن نــوع (‪ )...‬بقيــادة املتهــم‪ .....‬ويرفقــه املتهمــان ‪ .....‬و ‪ .....‬وبإستشــمامهم‬\n     ‫جمعيــا تبــن أنهــم يف حالــة ســكر وبتفتيــش املركبــة عثــر فيهــا علــى‬\n     ‫قــارورة بهــا النصــف مــن الشــراب املســكر فتــم التحفــظ عليهم وبســماع‬\n     ‫أقوالهــم مــن قبــل رجــال الضبــط مبركــز شــرطة جنــوب الدمــام أقــروا‬\n     ‫بصحــة واقعــة القبــض عليهــم وأقــر املتهــم ‪ .....‬بحيــازة وشــرب املســكر‬\n\n‫‪15‬‬\n\f‫يف حــن نفــى املتهمــان ‪.....‬و‪.....‬صحــة مــا ورد مبحضــر االستشــمام‬\n‫وبنــاء علــى مــا ذكــر أقــرر اتهــام كل مــن‪.......... -3 ..... -2 ..... -1 :‬‬\n‫باآلتــي‪ -1 :‬شــرب املســكر ‪ -2‬قيــادة املتهــم الثانــي ‪.....‬الســيارة حتــت‬\n‫تأثيــر املســكر ‪ -3‬حيــازة املتهــم األول ‪.....‬لقــارورة مــاء بهــا والنصــف‬\n‫مــن الشــراب املســكر بقصــد الشــرب وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ -1‬مــا ورد بأقوالهــم األوليــة املنــوه عنهــا املدونــة علــى الصفحــات رقــم‬\n‫(‪ )15-10‬مــن ملــف تقريــر األحــوال األمنيــة املوحــد ‪ -2‬محضــر تنفيــذ‬\n‫املهمــة املنــوه عنــه املرفــق علــى اللفــة رقــم (‪ -3 )2‬محضــر االستشــمام‬\n‫املنــوه عنــه املرفــق علــى اللفــة رقــم (‪ )3‬وبالبحــث عــن ســوابقهم لــم يعثــر‬\n‫لهــم علــى ســوابق وحيــث إن مــا أقــدم عليــه املتهمــون وهــم بكامــل‬\n‫أهليتهــم املعتبــرة شــرعا فعــل محــرم شــرعا ومجــرم نظامــا ممــا يتعــن‬\n‫معــه إحالتهــم إلــى احملكمــة اجلزائيــة وفــق املادتــن (‪ )128-126‬مــن‬\n‫نظــام اإلجــراءات اجلزائيــة للمطالبــة مبــا يلــي‪ :‬أوال إثبــات شــربهم‬\n‫جمعيــا للمســكر واحلكــم عليهــم بحــد الســكر لقــاء ذلــك‪ .‬ثانيــا‪:‬‬\n‫إثبــات حيــازة املتهــم األول ‪ .....‬لقــارورة مــاء بهــا النصــف مــن الشــراب‬\n‫املســكر بقصــد الشــرب واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع‬\n‫غيــره‪ .‬ثالثــا‪ :‬إثبــات قيــادة املتهــم ‪ .....‬للســيارة حتــت تأثيــر املســكر وفــق‬\n‫الفقــرة رقــم (‪ )8‬مــن اجلــدول رقــم (‪ )1‬امللحــق بنظــام املــرور وإفهامــه بــأن‬\n‫عقوبتــه الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )68‬مــن نظــام املــرور‬\n‫تقــرر مــن اجلهــة املختصــة وفــق الفقــرة (‪ )2‬مــن قــرار مجلــس الــوزراء‬\n‫رقــم (‪ )315‬وتاريــخ ‪1428/10/24‬ه ـ هكــذا ادعــى وبعــرض الدعــوى‬\n‫ا مــا ذكــره املدعــي‬     ‫علــى املدعــى عليــه احلاضــر ‪ ..........‬أجــاب قائ ـ ً‬\n‫العــام مــن قيامــي بشــرب املســكر فذلــك غيــر صحيــح ولــم أقــم بشــرب‬\n\n\n                                                                                         ‫‪16‬‬\n\f     ‫املســكر هكــذا أجــاب وأمــا املدعــى عليهمــا ‪.....‬و‪.....‬فلــم يحضــرا ثــم‬\n     ‫جــرى عــرض مــا ذكــره املدعــى عليــه وبســؤال املدعــي العــام البينــة‬\n     ‫علــى دعــواه قــال أطلــب الرجــوع إلــى املعاملــة هكــذا أجــاب ثــم جــرى‬\n     ‫الرجــوع إلــى املعاملــة فوجــدت علــى لفــة رقــم (‪ )3‬محضــر استشــمام‬\n     ‫ـاء علــى مــا‬\n                 ‫املتضمــن القبــض علــى املدعــى عليهــم وهــم بحالــة ســكر فبنـ ً‬\n     ‫تقــدم مــن دعــوى املدعــي العــام وإجابــة املدعــى عليــه وإنــكاره للدعــوى‬\n     ‫ومبــا أن محضــر االستشــمام قرينــة تؤيــد دعــوى املدعــي العــام ومبــا أن‬\n     ‫احلــدود تــدرأ بالشــبهات ونظــر ًا ملــا ذكــره الفقهــاء ومــن ذلــك مــا نــص‬\n     ‫عليــه البهوتــي يف كشــاف القنــاع (‪ )101/14‬بقولــه ( وال يحــد بوجــود‬\n     ‫رائحــة اخلمــر منــه واحلــد يــدرأ بالشــبهة لكــن يعــزر ) لــذا كلــه لــم تثبــت‬\n     ‫لــدي إدانــة املدعــى عليــه ‪.....‬بشــرب املســكر وقــررت اآلتــي‪ :‬أوالً‪ :‬رد‬\n     ‫طلــب املدعــي العــام بإقامــة حــد املســكر علــى املدعــى عليــه ‪.....‬لعــدم‬\n     ‫ثبوتــه‪ .‬ثاني ـاً‪ :‬تعزيــر املدعــى عليــه ‪.....‬باجللــد ثالثــن جلــدة دفعــة واحــدة‬\n     ‫لقــاء شــبهة شــرب املســكر وبــكل مــا تقــدم حكمــت وبعــرض احلكــم‬\n     ‫علــى الطرفــن قــرر املدعــى عليــه القناعــة باحلكــم كمــا قــرر املدعــي‬\n     ‫العــام االعتــراض علــى احلكــم واالكتفــاء بالئحــة الدعــوى العامــة‬\n     ‫وســوف يجــري نظــر الدعــوى بحــق املدعــى عليهمــا ‪.....‬و‪.....‬يف حــال‬\n     ‫حضورهمــا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر‬\n                                                                      ‫يف ‪1434/1/20‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n     ‫لــدى احملكمــة برقــم ‪/34/332748‬ج‪ 2‬وتاريــخ ‪1434/2/10‬ه ـ الواردة‬\n     ‫مــن فضيلــة رئيــس احملكمة اجلزائيــة مبدينة الدمام برقم ‪32/660647‬‬\n\n\n‫‪17‬‬\n\f‫وتاريــخ ‪1434/2/5‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ‪ .....‬املســجل برقــم ‪ 3418751‬وتاريــخ ‪1434/1/20‬ه ـ‬\n‫كل مــن‪ ...../1 :‬و‪ ...../2‬و‪...../3‬‬  ‫اخلــاص بدعــوى املدعــي العــام ضــد ٍ‬\n‫يف قضيــة مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n‫املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                     ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/2/16‬هــ‪.‬‬\n\n\n\n\n                                                                                    ‫‪18‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":14,"source_page_end":18,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"26eb54ef1f82a93c102270e85573ee567e01b4b71b5bc8acfc111e3583340483","normalized_text_hash":"a166a7a41217b08398f5c7ec20977239fcf9accf6ded6153774c9b6fabfc9213","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p14-3418751"}]$archive_payload$::jsonb) AS x LIMIT 25
